// Quote of the day list (365 quotes, one per day).
// DO NOT reorder or remove entries: a quote's index == dayNumber % 365.
// To extend: append new quotes ONLY at the end (do not delete or reorder),
// and the epoch in lib/quoteOfTheDay.js must stay fixed.
// Entries with "v: true" have wording/attribution that needs human verification
// (see QUOTES_VERIFY_TODO.md).

export const gmQuotes = [
  {"id":"Q0360","en":"Chess is a game for a lifetime of learning.","ta":"சதுரங்கம் என்பது வாழ்நாள் முழுவதும் கற்றுக்கொண்டே இருக்க வேண்டிய விளையாட்டு.","author":"Emanuel Lasker","v":true},
  {"id":"Q0077","en":"Every game of chess is a work of art. The only thing that matters is whether you can play brilliantly.","ta":"சதுரங்கத்தின் ஒவ்வொரு ஆட்டமும் ஒரு கலைப்படைப்பு. முக்கியமானது ஒன்றே: உங்களால் அற்புதமாக விளையாட முடிகிறதா என்பதுதான்.","author":"Garry Kasparov"},
  {"id":"Q0233","en":"Each player has his own style of play; that is what makes chess a game of personalities.","ta":"ஒவ்வொரு வீரருக்கும் தனக்கே உரிய ஆட்டப் பாணி இருக்கும்; அதுதான் சதுரங்கத்தை ஆளுமைகளின் ஆட்டமாக மாற்றுகிறது.","author":"Mikhail Tal","v":true},
  {"id":"Q0212","en":"Learn the principles, then trust your intuition.","ta":"முதலில் அடிப்படைக் கோட்பாடுகளைக் கற்றுக்கொள்ளுங்கள்; பிறகு உங்கள் உள்ளுணர்வை நம்புங்கள்.","author":"Reuben Fine","v":true},
  {"id":"Q0138","en":"By all means examine the games of the great chess players, but do not swallow them whole. Their games are valuable not for their separate moves, but for their vision of chess, their way of thinking.","ta":"மாபெரும் சதுரங்க வீரர்களின் ஆட்டங்களை நிச்சயமாக ஆராயுங்கள்; ஆனால் அவற்றை அப்படியே முழுமையாக விழுங்கிவிடாதீர்கள். அவர்களின் ஆட்டங்களின் மதிப்பு தனித்தனி நகர்வுகளில் இல்லை; அவர்களின் சதுரங்கப் பார்வையிலும் சிந்தனை முறையிலும்தான் இருக்கிறது.","author":"Anatoly Karpov","v":true},
  {"id":"Q0082","en":"If you wish to succeed, you must brave the risk of failure.","ta":"வெற்றி பெற விரும்பினால், தோல்வியின் அபாயத்தைத் துணிவுடன் எதிர்கொள்ள வேண்டும்.","author":"Garry Kasparov","v":true},
  {"id":"Q0217","en":"Even the best chess players in the world make mistakes. The difference is that they make fewer mistakes than their opponents.","ta":"உலகின் சிறந்த சதுரங்க வீரர்கள்கூட தவறு செய்கிறார்கள். வித்தியாசம் என்னவென்றால், அவர்கள் தங்கள் எதிரிகளைவிடக் குறைவாகத் தவறு செய்கிறார்கள்.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0079","en":"Chess is life in miniature.","ta":"சதுரங்கம் என்பது வாழ்க்கையின் ஒரு சிறிய வடிவம்.","author":"Garry Kasparov","v":true},
  {"id":"Q0235","en":"The most difficult game to win is a won game.","ta":"வெல்ல மிகவும் கடினமான ஆட்டம், ஏற்கனவே வென்றுவிட்டதாகத் தோன்றும் ஆட்டமே.","author":"William Ewart Napier","v":true},
  {"id":"Q0236","en":"In blitz the fish are caught, in classical chess the dragons are slain.","ta":"பிளிட்ஸில் மீன்கள் பிடிபடுகின்றன; கிளாசிக்கல் சதுரங்கத்தில் டிராகன்கள் வீழ்த்தப்படுகின்றன.","author":"Anish Giri","v":true},
  {"id":"Q0350","en":"Chess is a game where every move is the first move.","ta":"சதுரங்கத்தில் ஒவ்வொரு நகர்வும் முதல் நகர்வாகவே இருக்கும்.","author":"Mikhail Tal","v":true},
  {"id":"Q0329","en":"A good player always keeps his options open.","ta":"நல்ல வீரர் எப்போதும் தனக்குப் பல வாய்ப்புகளைத் திறந்தே வைத்திருப்பார்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0033","en":"Chess, like all other things, can be learned up to a point and no further. The rest depends on the nature of the person.","ta":"மற்ற எல்லாவற்றையும்போல சதுரங்கத்தையும் ஒரு கட்டம் வரைதான் கற்றுக்கொள்ள முடியும்; அதற்கு மேல் முடியாது. மீதி அந்த மனிதரின் இயல்பைப் பொறுத்தது.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0187","en":"It very much depends on the position.","ta":"அது முழுக்க முழுக்க நிலையைப் பொறுத்தது.","author":"Boris Spassky","v":true},
  {"id":"Q0198","en":"The essence of chess is struggle, not art.","ta":"சதுரங்கத்தின் அடிப்படைச் சாரம் போராட்டமே, கலை அல்ல.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0274","en":"The endgame is the kingdom of the king.","ta":"இறுதி ஆட்டம் அரசனின் ராஜ்யம்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0291","en":"A chess master should hold a whole game in his head, from beginning to end.","ta":"சதுரங்க மாஸ்டர் ஒரு முழு ஆட்டத்தையும் ஆரம்பம் முதல் இறுதி வரை தன் மனதில் வைத்திருக்க வேண்டும்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0357","en":"A chess game is a story told in moves.","ta":"சதுரங்க ஆட்டம் என்பது நகர்வுகளால் சொல்லப்படும் ஒரு கதை.","author":"Mikhail Tal","v":true},
  {"id":"Q0271","en":"The moves you don't make are often more important than the moves you make.","ta":"நீங்கள் செய்யாத நகர்வுகள், நீங்கள் செய்யும் நகர்வுகளைவிடப் பல நேரங்களில் முக்கியமானவை.","author":"Boris Spassky","v":true},
  {"id":"Q0190","en":"Help your pieces so they can help you.","ta":"உங்கள் காய்களுக்கு உதவுங்கள்; அப்போதுதான் அவை உங்களுக்கு உதவும்.","author":"Paul Morphy","v":true},
  {"id":"Q0295","en":"The game of chess is the game of patience and precision.","ta":"சதுரங்கம் பொறுமையும் துல்லியமும் கொண்ட விளையாட்டு.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0284","en":"The more you suffer the endgame, the more you will enjoy the middlegame.","ta":"இறுதி ஆட்டத்தில் அதிகம் கஷ்டப்படยิ่ง நடு ஆட்டத்தை அதிகம் ரசிப்பீர்கள்.","author":"Capablanca","v":true},
  {"id":"Q0184","en":"Chess is a constant struggle between my desire not to lose and my desire not to think.","ta":"தோற்கக் கூடாது என்ற என் விருப்பத்துக்கும், சிந்திக்கக் கூடாது என்ற என் விருப்பத்துக்கும் இடையே நடக்கும் தொடர் போராட்டமே சதுரங்கம்.","author":"Jan Gustafsson","v":true},
  {"id":"Q0327","en":"Chess is the game of the century, the game of every century.","ta":"சதுரங்கம் இந்த நூற்றாண்டின் விளையாட்டு; ஒவ்வொரு நூற்றாண்டின் விளையாட்டும் அதுவே.","author":"Yuri Averbakh","v":true},
  {"id":"Q0253","en":"A chess game is a forest: the player is the woodsman.","ta":"சதுரங்க ஆட்டம் ஒரு காடு; வீரன் அதில் மரம் வெட்டும் வனத்தொழிலாளி.","author":"Richard Réti","v":true},
  {"id":"Q0171","en":"Not all artists are chess players, but all chess players are artists.","ta":"எல்லா கலைஞர்களும் சதுரங்க வீரர்கள் அல்ல; ஆனால் எல்லா சதுரங்க வீரர்களும் கலைஞர்களே.","author":"Marcel Duchamp","v":true},
  {"id":"Q0022","en":"Erro ergo sum.","ta":"நான் தவறு செய்கிறேன், அதனால் நான் இருக்கிறேன்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0092","en":"Play the opening like a book, the middlegame like a magician, and the endgame like a machine.","ta":"தொடக்க ஆட்டத்தைப் புத்தகம் போலவும், நடு ஆட்டத்தை மந்திரவாதி போலவும், இறுதி ஆட்டத்தை இயந்திரம் போலவும் விளையாடுங்கள்.","author":"Rudolf Spielmann"},
  {"id":"Q0219","en":"In chess, you must be cruel to be kind.","ta":"சதுரங்கத்தில் நல்லது செய்ய வேண்டுமானால், சில நேரம் கடுமையாக இருக்க வேண்டும்.","author":"Nigel Short","v":true},
  {"id":"Q0331","en":"Chess is a battle of the inner self.","ta":"சதுரங்கம் என்பது உள்ளத்துக்குள் நடக்கும் போர்.","author":"Viktor Korchnoi","v":true},
  {"id":"Q0149","en":"In chess, as in life, opportunities slip by quickly.","ta":"சதுரங்கத்திலும் வாழ்க்கையிலும் வாய்ப்புகள் விரைவாக நழுவிவிடும்.","author":"Hikaru Nakamura","v":true},
  {"id":"Q0124","en":"Modern chess is too much concerned with things like pawn structure. Forget it, checkmate ends the game.","ta":"நவீன சதுரங்கம் சிப்பாய் அமைப்பு போன்ற விஷயங்களில் அதிகம் கவலைப்படுகிறது. அவற்றை மறந்துவிடுங்கள்; செக்மேட்தான் ஆட்டத்தை முடிக்கிறது.","author":"Nigel Short","v":true},
  {"id":"Q0252","en":"Chess is the only game in which the mind is the master of the body.","ta":"மனமே உடலுக்கு எஜமானாக இருக்கும் ஒரே விளையாட்டு சதுரங்கம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0087","en":"By strictly observing Botvinnik's rule regarding the thorough analysis of one's own games, I have come to realize that this provides the foundation for the continuous development of chess mastery.","ta":"தன் ஆட்டங்களை முழுமையாகப் பகுப்பாய்வு செய்ய வேண்டும் என்ற போட்வினிக்கின் விதியைக் கண்டிப்பாகப் பின்பற்றியதன் மூலம், அதுவே சதுரங்கத் தேர்ச்சியைத் தொடர்ந்து வளர்த்துக்கொள்வதற்கான அடித்தளம் என்பதை உணர்ந்தேன்.","author":"Garry Kasparov","v":true},
  {"id":"Q0012","en":"Some part of a mistake is always correct.","ta":"ஒவ்வொரு தவறிலும் ஏதோ ஒரு பகுதி எப்போதும் சரியாகவே இருக்கும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0215","en":"A sacrifice is the most beautiful move in chess.","ta":"தியாகம் செய்வதுதான் சதுரங்கத்தின் மிக அழகான நகர்வு.","author":"Rudolf Spielmann","v":true},
  {"id":"Q0152","en":"A bad plan is better than no plan at all.","ta":"மோசமான திட்டம்கூட திட்டமே இல்லாததைவிட நல்லது.","author":"Frank Marshall","v":true},
  {"id":"Q0354","en":"Chess is the only game where the luck of the draw has no place.","ta":"சீட்டுக் குலுக்கலின் அதிர்ஷ்டத்துக்கு இடமில்லாத ஒரே விளையாட்டு சதுரங்கம்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0231","en":"Chess is a game with a future.","ta":"எதிர்காலம் கொண்ட விளையாட்டு சதுரங்கம்.","author":"Julius Kedar","v":true},
  {"id":"Q0122","en":"Every chess master was once a beginner.","ta":"ஒவ்வொரு சதுரங்க மாஸ்டரும் ஒரு காலத்தில் ஆரம்பநிலை வீரராகத்தான் இருந்தார்.","author":"Irving Chernev","v":true},
  {"id":"Q0337","en":"Every pawn that advances is a commitment to a plan.","ta":"முன்னேறும் ஒவ்வொரு சிப்பாயும் ஒரு திட்டத்துக்கான உறுதிப்பாட்டைக் காட்டுகிறது.","author":"Aaron Nimzowitsch","v":true},
  {"id":"Q0300","en":"The game of chess is a duel of wills, a clash of ambitions.","ta":"சதுரங்கம் என்பது விருப்பங்களின் போட்டி; லட்சியங்களின் மோதல்.","author":"Bobby Fischer","v":true},
  {"id":"Q0309","en":"In chess, every piece has value; the trick is to give each the value it deserves.","ta":"சதுரங்கத்தில் ஒவ்வொரு காய்க்கும் மதிப்பு உண்டு; அதன் தகுதிக்கு ஏற்ற மதிப்பைக் கொடுப்பதே தந்திரம்.","author":"Aaron Nimzowitsch","v":true},
  {"id":"Q0316","en":"Watch the board, not the clock; the position speaks for itself.","ta":"கடிகாரத்தை அல்ல, பலகையைப் பாருங்கள்; நிலையே தன்னைத் தானே விளக்கும்.","author":"Mikhail Tal","v":true},
  {"id":"Q0200","en":"In chess, as in life, you get what you give.","ta":"சதுரங்கத்திலும் வாழ்க்கையிலும் நீங்கள் கொடுப்பதையே திரும்பப் பெறுவீர்கள்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0310","en":"The pleasure of chess is in the struggle, not merely in the victory.","ta":"சதுரங்கத்தின் இன்பம் வெற்றியில் மட்டுமல்ல, போராட்டத்திலும் இருக்கிறது.","author":"Boris Spassky","v":true},
  {"id":"Q0259","en":"Space is at a premium in chess; every square is valuable.","ta":"சதுரங்கத்தில் இடம் மிக மதிப்புமிக்கது; ஒவ்வொரு கட்டமும் விலைமதிப்பற்றது.","author":"Richard Réti","v":true},
  {"id":"Q0301","en":"Chess is a game that never ends; the lessons live forever.","ta":"சதுரங்கம் ஒருபோதும் முடிவடையாத விளையாட்டு; அதன் பாடங்கள் என்றென்றும் வாழும்.","author":"Boris Spassky","v":true},
  {"id":"Q0133","en":"Good players develop a fine sense of danger.","ta":"நல்ல வீரர்கள் ஆபத்தை முன்கூட்டியே உணரும் நுட்பமான உணர்வை வளர்த்துக்கொள்வார்கள்.","author":"Bent Larsen","v":true},
  {"id":"Q0348","en":"Chess is a ladder where every game is a step.","ta":"சதுரங்கம் ஒரு ஏணி; ஒவ்வொரு ஆட்டமும் அதில் ஒரு படி.","author":"Savielly Tartakower","v":true},
  {"id":"Q0342","en":"Chess is both a science and an art; that is its unique charm.","ta":"சதுரங்கம் அறிவியலும் கலையும் கலந்தது; அதுதான் அதன் தனித்துவமான கவர்ச்சி.","author":"Boris Spassky","v":true},
  {"id":"Q0328","en":"The mind is the chessboard; every thought is a move.","ta":"மனமே சதுரங்கப் பலகை; ஒவ்வொரு எண்ணமும் ஒரு நகர்வு.","author":"Mikhail Tal","v":true},
  {"id":"Q0280","en":"Chess is a mirror of the human mind; its moves reflect our thoughts.","ta":"சதுரங்கம் மனித மனதின் கண்ணாடி; அதன் நகர்வுகள் நம் எண்ணங்களைப் பிரதிபலிக்கின்றன.","author":"Nikolai Krogius","v":true},
  {"id":"Q0147","en":"It is better to overestimate your prospects than underestimate them.","ta":"உங்கள் வாய்ப்புகளைக் குறைத்து மதிப்பிடுவதைவிட அதிகமாக மதிப்பிடுவதே நல்லது.","author":"Magnus Carlsen","v":true},
  {"id":"Q0353","en":"The game of chess is an endless source of learning.","ta":"சதுரங்கம் என்பது முடிவில்லாத கற்றலுக்கான ஆதாரம்.","author":"Bobby Fischer","v":true},
  {"id":"Q0363","en":"A win by an unsound combination, however showy, fills me with artistic horror.","ta":"அடிப்படையில் தவறான ஒரு சேர்க்கை நகர்வால் வெல்வது, எவ்வளவு பிரமாதமாகத் தோன்றினாலும், கலைஞனாக எனக்கு அருவருப்பையே தருகிறது.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0057","en":"Whatever your opponent gives you, take, unless you see a good reason not to.","ta":"எதிரி கொடுப்பதை எல்லாம் எடுத்துக்கொள்ளுங்கள்; எடுக்கக்கூடாது என்பதற்கு நல்ல காரணம் தெரிந்தால் மட்டும் விட்டுவிடுங்கள்.","author":"Bobby Fischer","v":true},
  {"id":"Q0326","en":"In chess, one false step can undo a hundred good ones.","ta":"சதுரங்கத்தில் ஒரு தவறான நகர்வு நூறு நல்ல நகர்வுகளின் பயனையும் அழித்துவிடும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0205","en":"Tactics is knowing what to do when there is something to do.","ta":"தந்திர நகர்வுகள் என்றால், ஏதாவது செய்ய வேண்டிய நிலையில் என்ன செய்வது என்பதை அறிவதாகும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0279","en":"The strongest players are those who enjoy the game for its own sake.","ta":"விளையாட்டை அதற்காகவே ரசிப்பவர்களே மிக வலுவான வீரர்கள்.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0270","en":"Chess is a game that humbles you and lifts you at the same time.","ta":"சதுரங்கம் உங்களைத் தாழ்த்தியும் உயர்த்தியும் ஒரே நேரத்தில் செய்யும் விளையாட்டு.","author":"Judit Polgár","v":true},
  {"id":"Q0230","en":"The chessboard is the world, the pieces are the phenomena of the universe, the rules of the game are what we call the laws of Nature.","ta":"சதுரங்கப் பலகை உலகம்; காய்கள் பிரபஞ்சத்தின் நிகழ்வுகள்; விளையாட்டின் விதிகள்தான் நாம் இயற்கையின் விதிகள் என்பவை.","author":"Thomas Henry Huxley","v":true},
  {"id":"Q0060","en":"Tactics flow from a superior position.","ta":"சிறந்த நிலையிலிருந்தே தந்திர நகர்வுகள் பிறக்கின்றன.","author":"Bobby Fischer","v":true},
  {"id":"Q0288","en":"Chess is a game where the loser is the one who makes the last mistake.","ta":"சதுரங்கத்தில் கடைசியாகத் தவறு செய்பவரே தோற்பார்.","author":"Mikhail Tal","v":true},
  {"id":"Q0343","en":"The player who owns the center owns the game.","ta":"மையத்தைக் கட்டுப்படுத்துபவரே ஆட்டத்தையும் கட்டுப்படுத்துகிறார்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0315","en":"Chess is a beautiful game; it is a dance of the mind.","ta":"சதுரங்கம் அழகான விளையாட்டு; அது மனதின் நடனம்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0361","en":"In chess, beauty is the first test; there is no permanent place in this world for ugly chess.","ta":"சதுரங்கத்தில் அழகுதான் முதல் அளவுகோல்; அழகற்ற சதுரங்கத்துக்கு இந்த உலகில் நிரந்தர இடமில்லை.","author":"Mikhail Tal","v":true},
  {"id":"Q0333","en":"Chess is a game for all ages; its beauty never ages.","ta":"எல்லா வயதினருக்கும் ஏற்ற விளையாட்டு சதுரங்கம்; அதன் அழகு என்றும் முதுமையடையாது.","author":"Boris Spassky","v":true},
  {"id":"Q0258","en":"The only pawn that never moves is a dead pawn.","ta":"ஒருபோதும் நகராத சிப்பாய் இறந்த சிப்பாய்தான்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0167","en":"Openings teach you openings. Endgames teach you chess.","ta":"தொடக்க ஆட்டங்கள் உங்களுக்குத் தொடக்கங்களைக் கற்பிக்கும்; இறுதி ஆட்டங்கள் சதுரங்கத்தையே கற்பிக்கும்.","author":"Stephan Gerzadowicz","v":true},
  {"id":"Q0320","en":"Chess is a game of courage: the courage to sacrifice and the courage to defend.","ta":"சதுரங்கம் துணிச்சலின் விளையாட்டு: தியாகம் செய்யும் துணிச்சல், தற்காத்துக்கொள்ளும் துணிச்சல்.","author":"Rudolf Spielmann","v":true},
  {"id":"Q0080","en":"I used to attack because it was the only thing I knew. Now I attack because I know it works best.","ta":"முன்பு எனக்குத் தெரிந்த ஒரே விஷயம் தாக்குதல்தான், அதனால்தான் தாக்கினேன். இப்போது தாக்குதல்தான் சிறந்தது என்று தெரிந்ததால் தாக்குகிறேன்.","author":"Garry Kasparov","v":true},
  {"id":"Q0254","en":"The most important principle of the opening is rapid development.","ta":"தொடக்க ஆட்டத்தின் மிக முக்கியமான கொள்கை, காய்களை விரைவாக வளர்த்தெடுப்பதே.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0237","en":"Chess is ninety-nine percent tactics.","ta":"சதுரங்கம் தொண்ணூற்று ஒன்பது சதவீதம் தந்திர நகர்வுகள்தான்.","author":"Richard Teichmann","v":true},
  {"id":"Q0002","en":"When you see a good move, look for a better one.","ta":"நல்ல நகர்வு ஒன்று தெரிந்தால், அதைவிடச் சிறந்ததைத் தேடுங்கள்.","author":"Emanuel Lasker"},
  {"id":"Q0159","en":"I never read a chess book until I was already a master.","ta":"நான் மாஸ்டர் ஆன பிறகுதான் முதன்முதலாக ஒரு சதுரங்கப் புத்தகத்தைப் படித்தேன்.","author":"Reuben Fine","v":true},
  {"id":"Q0144","en":"Be well enough prepared that preparation will not play a role.","ta":"எவ்வளவு நன்றாகத் தயாராக வேண்டுமென்றால், தயாரிப்பே ஒரு பொருட்டாக இருக்காது.","author":"Magnus Carlsen","v":true},
  {"id":"Q0053","en":"Patzer sees a check, gives a check.","ta":"பலவீனமான வீரர் சாக் வாய்ப்பைப் பார்த்தால் உடனே சாக் கொடுத்துவிடுவார்.","author":"Bobby Fischer","v":true},
  {"id":"Q0121","en":"Methodical thinking is of more use in chess than inspiration.","ta":"சதுரங்கத்தில் உத்வேகத்தைவிட முறையான சிந்தனையே அதிகப் பயன் தரும்.","author":"C.J.S. Purdy","v":true},
  {"id":"Q0098","en":"Even the laziest king flees wildly in the face of a double check.","ta":"இரட்டைச் சாக் வந்தால், மிகச் சோம்பேறி அரசன்கூட பதறி ஓடுவான்.","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0244","en":"Never hurry in chess; think twice before you move.","ta":"சதுரங்கத்தில் அவசரப்படாதீர்கள்; நகர்வு செய்வதற்கு முன் இருமுறை சிந்தியுங்கள்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0241","en":"Chess is a game of coordination; the pieces must help each other.","ta":"ஒருங்கிணைப்பின் விளையாட்டு சதுரங்கம்; காய்கள் ஒன்றுக்கொன்று உதவ வேண்டும்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0179","en":"Pass me a bacon sandwich.","ta":"எனக்கு ஒரு பேக்கன் சாண்ட்விச் நீட்டுங்கள்.","author":"Boris Spassky","v":true},
  {"id":"Q0221","en":"One must be a great optimist to play chess; it is not a game for pessimists.","ta":"சதுரங்கம் விளையாட பெரும் நம்பிக்கையாளராக இருக்க வேண்டும்; அது அவநம்பிக்கையாளர்களுக்கான விளையாட்டல்ல.","author":"Mikhail Tal","v":true},
  {"id":"Q0266","en":"In chess, every piece moves with purpose; every move is a statement of will.","ta":"சதுரங்கத்தில் ஒவ்வொரு காயும் நோக்கத்துடன் நகர்கிறது; ஒவ்வொரு நகர்வும் விருப்பத்தின் அறிக்கை.","author":"Alexander Alekhine","v":true},
  {"id":"Q0322","en":"Every move in chess is a decision; every decision shapes the outcome.","ta":"சதுரங்கத்தின் ஒவ்வொரு நகர்வும் ஒரு முடிவு; ஒவ்வொரு முடிவும் விளைவை வடிவமைக்கிறது.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0095","en":"The passed pawn is a criminal who should be kept under lock and key.","ta":"வழியைத் தாண்டிச் செல்லும் சிப்பாய் ஒரு குற்றவாளி; அவனைப் பூட்டும் கதவுக்குப் பின்னால்தான் வைத்திருக்க வேண்டும்.","author":"Aron Nimzowitsch"},
  {"id":"Q0245","en":"The mistakes are all there on the board, waiting to be made.","ta":"தவறுகள் எல்லாம் பலகையிலேயே இருக்கின்றன, செய்யப்படுவதற்காகக் காத்திருக்கின்றன.","author":"Savielly Tartakower","v":true},
  {"id":"Q0201","en":"Openings are for amateurs. Real chess is played in the middlegame and endgame.","ta":"தொடக்க ஆட்டம் அமெச்சூர்களுக்கானது. உண்மையான சதுரங்கம் நடு ஆட்டத்திலும் இறுதி ஆட்டத்திலும்தான் விளையாடப்படுகிறது.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0032","en":"Chess serves, like few things in this world, to distract and momentarily forget the concerns of daily life.","ta":"இந்த உலகில் சில விஷயங்களே செய்வது போல, சதுரங்கம் அன்றாட வாழ்வின் கவலைகளைத் தற்காலிகமாக மறக்கச் செய்கிறது.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0135","en":"Chess is everything: art, science, and sport.","ta":"சதுரங்கம் எல்லாமும்தான்: கலை, அறிவியல், விளையாட்டு.","author":"Anatoly Karpov","v":true},
  {"id":"Q0211","en":"Chess is a mirror of the human condition.","ta":"மனித நிலையின் கண்ணாடி சதுரங்கம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0210","en":"The worst thing in chess is to play without a plan.","ta":"சதுரங்கத்தில் மிக மோசமானது, திட்டமில்லாமல் விளையாடுவதே.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0260","en":"In chess, one small mistake is often punished like a serious crime.","ta":"சதுரங்கத்தில் ஒரு சிறிய தவறுகூட பெருங்குற்றம் போலவே தண்டிக்கப்படுகிறது.","author":"A. A. Kotov","v":true},
  {"id":"Q0009","en":"Tactics is knowing what to do when there is something to do; strategy is knowing what to do when there is nothing to do.","ta":"தந்திர நகர்வுகள் என்பது, ஏதாவது செய்ய வேண்டிய நிலையில் என்ன செய்வது என்று அறிவது; ஆட்டத் திட்டம் என்பது, செய்ய ஒன்றுமில்லாத நிலையில் என்ன செய்வது என்று அறிவது.","author":"Savielly Tartakower"},
  {"id":"Q0029","en":"I see only one move ahead, but it is always the correct one.","ta":"நான் ஒரே ஒரு நகர்வை மட்டுமே முன்னால் பார்க்கிறேன்; ஆனால் அது எப்போதும் சரியானதாகவே இருக்கிறது.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0195","en":"The beauty of chess is that it is not about luck. The stronger player always wins, and if he makes a mistake, he deserves to lose.","ta":"சதுரங்கத்தின் அழகே அதில் அதிர்ஷ்டத்துக்கு இடமில்லாததுதான். வலுவான வீரனே எப்போதும் வெல்கிறான்; அவன் தவறு செய்தால் தோற்கத் தகுந்தவனே.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0191","en":"The ability to play chess well is the sign of a wasted life.","ta":"சதுரங்கத்தை நன்றாக விளையாடும் திறன், வீணான வாழ்க்கையின் அடையாளம்.","author":"Paul Morphy","v":true},
  {"id":"Q0248","en":"A well-developed position covers a multitude of sins.","ta":"நன்கு வளர்ந்த நிலை ஏராளமான குறைகளை மறைத்துவிடும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0177","en":"Chess is rarely a game of ideal moves. Almost always, a player faces a series of difficult consequences whichever move he makes.","ta":"சதுரங்கம் அரிதாகவே சிறந்த நகர்வுகளின் ஆட்டமாக இருக்கிறது. எந்த நகர்வைச் செய்தாலும், கிட்டத்தட்ட எப்போதும் வீரன் தொடர்ச்சியான கடின விளைவுகளை எதிர்கொள்ள வேண்டியிருக்கிறது.","author":"David Shenk","v":true},
  {"id":"Q0199","en":"Chess is a great test of patience and nerve.","ta":"பொறுமைக்கும் மனதிடத்துக்கும் சதுரங்கம் சிறந்த சோதனை.","author":"George Koltanowski","v":true},
  {"id":"Q0106","en":"One does not have to play well; it is enough to play better than your opponent.","ta":"நீங்கள் நன்றாக விளையாட வேண்டிய அவசியமில்லை; எதிரியைவிடச் சிறப்பாக விளையாடினால் போதும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0242","en":"A player who sacrifices a piece must keep attacking.","ta":"ஒரு காயைத் தியாகம் செய்யும் வீரன் தொடர்ந்து தாக்கிக்கொண்டே இருக்க வேண்டும்.","author":"Rudolf Spielmann","v":true},
  {"id":"Q0174","en":"Many people are skilful chess players, though in many instances their brains compare unfavourably with the cognitive faculties of a rabbit.","ta":"பலர் திறமையான சதுரங்க வீரர்களாக இருக்கிறார்கள்; ஆனால் பல சமயங்களில் அவர்களின் அறிவுத்திறன் ஒரு முயலின் அறிவுத்திறனைவிடக் கேவலமாகவே இருக்கிறது.","author":"James Mortimer","v":true},
  {"id":"Q0189","en":"Avoid the crowd. Do your own thinking independently.","ta":"கூட்டத்தைத் தவிர்த்திடுங்கள். சொந்தச் சிந்தனையைச் சுதந்திரமாகச் செய்யுங்கள்.","author":"Bobby Fischer","v":true},
  {"id":"Q0173","en":"The only thing chess players have in common is chess.","ta":"சதுரங்க வீரர்களுக்குப் பொதுவான ஒரே விஷயம் சதுரங்கம்தான்.","author":"Lodewijk Prins","v":true},
  {"id":"Q0158","en":"Discovered check is the dive bomber of the chessboard.","ta":"வெளிப்படுத்தப்பட்ட சாக் என்பது சதுரங்கப் பலகையின் குண்டுவீச்சு விமானம்.","author":"Reuben Fine","v":true},
  {"id":"Q0182","en":"Morphy was probably the greatest genius of them all.","ta":"எல்லோரிலும் மிகப் பெரிய மேதை மார்பியாகவே இருந்திருக்க வேண்டும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0041","en":"Do not even mention losing to me. I cannot stand to think of it.","ta":"தோல்வியைப் பற்றி என்னிடம் பேசவே வேண்டாம்; அதை நினைத்தாலே என்னால் தாங்கிக்கொள்ள முடியாது.","author":"Bobby Fischer","v":true},
  {"id":"Q0349","en":"In chess, the calm player wins the storm.","ta":"சதுரங்கத்தில் அமைதியான வீரனே புயலை வெல்கிறான்.","author":"Boris Spassky","v":true},
  {"id":"Q0180","en":"My God, he plays so simply!","ta":"கடவுளே, அவன் எத்தனை எளிமையாக விளையாடுகிறான்!","author":"Alexei Suetin","v":true},
  {"id":"Q0010","en":"No one ever won a game by resigning.","ta":"விட்டுக்கொடுத்து யாரும் ஒரு ஆட்டத்தை வென்றதில்லை.","author":"Savielly Tartakower"},
  {"id":"Q0165","en":"Half the variations calculated in a tournament game turn out to be completely superfluous. Unfortunately, no one knows in advance which half.","ta":"போட்டி ஆட்டத்தில் கணக்கிட்ட வழிமுறைகளில் பாதி முற்றிலும் தேவையற்றவையாகிவிடும். துரதிர்ஷ்டவசமாக, எந்தப் பாதி என்று முன்கூட்டியே யாருக்கும் தெரியாது.","author":"Jan Timman","v":true},
  {"id":"Q0323","en":"Chess is a game that respects preparation.","ta":"தயாரிப்பை மதிக்கும் விளையாட்டு சதுரங்கம்.","author":"Garry Kasparov","v":true},
  {"id":"Q0042","en":"Chess demands total concentration.","ta":"சதுரங்கம் முழுமையான செறிவைக் கோருகிறது.","author":"Bobby Fischer","v":true},
  {"id":"Q0265","en":"The heart of chess is the mind; the mind is the heart of the game.","ta":"சதுரங்கத்தின் இதயம் மனம்; மனமே விளையாட்டின் இதயம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0340","en":"A single glance at the board can change the course of a game.","ta":"பலகையின் மீதான ஒரே பார்வை ஆட்டத்தின் போக்கையே மாற்றிவிடும்.","author":"Garry Kasparov","v":true},
  {"id":"Q0031","en":"I have learned as much from most of my defeats as from a few victories.","ta":"என் சில வெற்றிகளிலிருந்து எவ்வளவு கற்றுக்கொண்டேனோ, அவ்வளவையே என் தோல்விகளின் பெரும்பாலானவற்றிலிருந்தும் கற்றுக்கொண்டேன்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0226","en":"The hardest thing in chess is to play a correct game.","ta":"சதுரங்கத்தில் மிகக் கடினமான விஷயம், சரியான ஆட்டத்தை விளையாடுவதே.","author":"Emanuel Lasker","v":true},
  {"id":"Q0364","en":"Chess is a matter of vanity.","ta":"வீண் பெருமையின் விஷயம்தான் சதுரங்கம்.","author":"Boris Spassky","v":true},
  {"id":"Q0036","en":"Chess is war over the board. The object is to crush the opponent's mind.","ta":"சதுரங்கம் என்பது பலகை மீதான போர். நோக்கம் எதிரியின் மனதை நொறுக்குவதே.","author":"Bobby Fischer"},
  {"id":"Q0163","en":"Of chess it has been said that life is not long enough for it, but that is the fault of life, not chess.","ta":"சதுரங்கத்துக்கு வாழ்நாள் போதாது என்று சொல்லப்படுகிறது; அது வாழ்க்கையின் குற்றமே, சதுரங்கத்தின் குற்றமல்ல.","author":"William Ewart Napier","v":true},
  {"id":"Q0027","en":"The beauty of a move lies not in its appearance but in the thought behind it.","ta":"ஒரு நகர்வின் அழகு அதன் தோற்றத்தில் அல்ல; அதன் பின்னால் இருக்கும் சிந்தனையில் இருக்கிறது.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0034","en":"Adequate compensation for a sacrifice is having a sound combination leading to a winning position.","ta":"ஒரு தியாகத்துக்குத் தகுந்த ஈடு என்பது, வெற்றி நிலைக்கு இட்டுச் செல்லும் திடமான சேர்க்கை நகர்வைக் கொண்டிருப்பதே.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0207","en":"Chess demands total concentration, a kind of meditation.","ta":"சதுரங்கம் முழுமையான செறிவைக் கோருகிறது; அது ஒருவித தியானம்.","author":"Viswanathan Anand","v":true},
  {"id":"Q0160","en":"I love all positions. Give me a difficult positional game, and I will play it. Give me a bad position, and I will defend it. But totally winning positions I cannot stand.","ta":"நான் எல்லா நிலைகளையும் விரும்புகிறேன். கடினமான நிலைப்பாட்டு ஆட்டத்தைக் கொடுங்கள், விளையாடுகிறேன்; மோசமான நிலையைக் கொடுங்கள், தற்காத்துக்கொள்கிறேன். ஆனால் முழுவதுமாக வெற்றி நிலைகளை என்னால் தாங்கவே முடியாது.","author":"Jan Hein Donner","v":true},
  {"id":"Q0063","en":"Genius. It is a word. What does it really mean? If I win, I am a genius. If I do not, I am not.","ta":"மேதை என்பது ஒரு சொல்தான். அதன் உண்மையான பொருள் என்ன? நான் வென்றால் நான் மேதை; இல்லையென்றால் இல்லை.","author":"Bobby Fischer","v":true},
  {"id":"Q0081","en":"When your opponent is in trouble, do not let him off the hook.","ta":"எதிரி சிக்கலில் இருக்கும்போது, அவனைத் தப்பவிடாதீர்கள்.","author":"Garry Kasparov","v":true},
  {"id":"Q0302","en":"In chess, think of the board as your canvas and the pieces as your paint.","ta":"சதுரங்கத்தில் பலகையை உங்கள் கேன்வாஸாகவும், காய்களை வண்ணங்களாகவும் எண்ணுங்கள்.","author":"Richard Réti","v":true},
  {"id":"Q0145","en":"Some people think that if their opponent plays a beautiful game, it is OK to lose. I do not. You have to be merciless.","ta":"எதிரி அழகான ஆட்டத்தை விளையாடினால் தோற்பதும் தகும் என்று சிலர் நினைக்கிறார்கள். நான் அப்படி நினைக்கவில்லை. இரக்கமே இல்லாமல் இருக்க வேண்டும்.","author":"Magnus Carlsen","v":true},
  {"id":"Q0157","en":"Chess is a fairy tale of 1001 blunders.","ta":"சதுரங்கம் என்பது 1001 தவறுகளின் தேவதைக் கதை.","author":"Reuben Fine","v":true},
  {"id":"Q0023","en":"If errors did not exist, they should be invented.","ta":"தவறுகள் இல்லாதிருந்தால், அவற்றைக் கண்டுபிடித்தாக வேண்டும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0123","en":"The pin is mightier than the sword.","ta":"குத்தீட்டியே வாளைவிட வலிமையானது.","author":"Fred Reinfeld","v":true},
  {"id":"Q0256","en":"To sacrifice the exchange is to give up a rook for a knight or bishop: sometimes the best investment.","ta":"கோட்டையைப் பரிமாற்றம் செய்வது என்பது ஒரு கோட்டையைக் குதிரைக்கோ மந்திரிக்கோ விட்டுக்கொடுப்பது: சில நேரங்களில் அதுவே சிறந்த முதலீடு.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0345","en":"In chess, the road to victory is paved with careful moves.","ta":"சதுரங்கத்தில் வெற்றிக்கான பாதை கவனமான நகர்வுகளால் அமைக்கப்படுகிறது.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0130","en":"Give me a difficult positional game, and I will play it. But a clear-cut tactical crush - that is a loss.","ta":"கடினமான நிலைப்பாட்டு ஆட்டத்தைக் கொடுங்கள், நான் விளையாடுகிறேன். ஆனால் தெளிவான தந்திர நொறுக்குதல் என்பது ஒரு தோல்விதான்.","author":"Tigran Petrosian","v":true},
  {"id":"Q0091","en":"Only the player with the initiative has the right to attack.","ta":"முன்முயற்சி கையில் இருக்கும் வீரனுக்கு மட்டுமே தாக்கும் உரிமை உண்டு.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0228","en":"To find the best move, look for the worst square for your piece, then move it there.","ta":"சிறந்த நகர்வைக் கண்டறிய, உங்கள் காய்க்கு மிக மோசமான சதுரத்தைத் தேடுங்கள்; பிறகு அங்கே அதை நகர்த்துங்கள்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0151","en":"Even a poor plan is better than no plan at all.","ta":"மோசமான திட்டம்கூட திட்டமே இல்லாததைவிடச் சிறந்தது.","author":"Mikhail Chigorin","v":true},
  {"id":"Q0061","en":"I am the best player in the world, and I am here to prove it.","ta":"உலகின் சிறந்த வீரன் நான்தான்; அதை நிரூபிக்கவே இங்கு வந்துள்ளேன்.","author":"Bobby Fischer","v":true},
  {"id":"Q0114","en":"One of the principal requisites of good chess is the ability to treat both middle and end game equally well.","ta":"நல்ல சதுரங்கத்தின் முக்கிய தேவைகளில் ஒன்று, நடு ஆட்டத்தையும் இறுதி ஆட்டத்தையும் சமமாகச் சிறப்பாகக் கையாளும் திறன்.","author":"Richard Réti","v":true},
  {"id":"Q0058","en":"White can always play differently, in which case he merely loses differently.","ta":"வெள்ளை எப்போதும் வேறுவிதமாக விளையாடலாம்; அப்படிச் செய்தால் அவன் வேறுவிதமாகவே தோற்பான்.","author":"Bobby Fischer","v":true},
  {"id":"Q0203","en":"Chess is a game of pure thought, a game without chance.","ta":"சதுரங்கம் தூய சிந்தனையின் விளையாட்டு, வாய்ப்பே இல்லாத விளையாட்டு.","author":"Alexander Alekhine","v":true},
  {"id":"Q0202","en":"The king is the most important piece: keep him safe.","ta":"அரசனே மிக முக்கியமான காய்; அவனைப் பாதுகாப்பாக வையுங்கள்.","author":"Philidor","v":true},
  {"id":"Q0015","en":"The move is there, but you must see it.","ta":"நகர்வு அங்கேதான் இருக்கிறது; ஆனால் அதை நீங்கள் காண வேண்டும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0196","en":"The combination player thinks ahead; the positional player thinks behind.","ta":"சேர்க்கை நகர்வு ஆட்டக்காரன் முன்னால் சிந்திக்கிறான்; நிலைப்பாட்டு ஆட்டக்காரன் பின்னால் சிந்திக்கிறான்.","author":"Richard Réti","v":true},
  {"id":"Q0069","en":"To play for a draw, at any rate with white, is to some degree a crime against chess.","ta":"சமநிலைக்காக விளையாடுவது, குறைந்தபட்சம் வெள்ளையுடன், ஓரளவு சதுரங்கத்துக்கு எதிரான குற்றமே.","author":"Mikhail Tal","v":true},
  {"id":"Q0246","en":"In chess, beauty is objective and truthful; it is geometry.","ta":"சதுரங்கத்தில் அழகு புறநிலை சார்ந்ததும் உண்மையானதும் ஆகும்; அது வடிவியல்.","author":"Mikhail Tal","v":true},
  {"id":"Q0035","en":"I do not believe in psychology. I believe in good moves.","ta":"நான் உளவியலை நம்பவில்லை. நல்ல நகர்வுகளையே நம்புகிறேன்.","author":"Bobby Fischer"},
  {"id":"Q0285","en":"In chess, the pieces are the language; the board is the stage.","ta":"சதுரங்கத்தில் காய்களே மொழி; பலகையே அரங்கம்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0105","en":"Up to this point White has been following well-known analysis. But now he makes a fatal error: he begins to use his own head.","ta":"இதுவரை வெள்ளை நன்கு அறியப்பட்ட பகுப்பாய்வையே பின்பற்றி வந்தது. ஆனால் இப்போது அது ஒரு மரண தவறு செய்கிறது: சொந்தத் தலையைப் பயன்படுத்தத் தொடங்குகிறது.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0319","en":"In chess, your opponent is your teacher.","ta":"சதுரங்கத்தில் உங்கள் எதிரியே உங்கள் ஆசிரியர்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0111","en":"The king is a fighting piece. Use it.","ta":"அரசன் ஒரு போரிடும் காய். அவனைப் பயன்படுத்துங்கள்.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0090","en":"Chess is the art which expresses the science of logic.","ta":"தர்க்கத்தின் அறிவியலை வெளிப்படுத்தும் கலைதான் சதுரங்கம்.","author":"Mikhail Botvinnik"},
  {"id":"Q0016","en":"Chess survives thanks to the mistakes made while playing it.","ta":"விளையாடும்போது செய்யப்படும் தவறுகளால்தான் சதுரங்கம் உயிர்வாழ்கிறது.","author":"Savielly Tartakower","v":true},
  {"id":"Q0052","en":"Draws make for dull chess; wins make for fighting chess.","ta":"சமநிலை முடிவுகள் சதுரங்கத்தைச் சப்பையாக்குகின்றன; வெற்றிகள் அதைப் போர்மயமாக்குகின்றன.","author":"Bobby Fischer","v":true},
  {"id":"Q0362","en":"You may learn much more from a game you lose than from a game you win.","ta":"வென்ற ஆட்டத்தைவிட, தோற்ற ஆட்டத்திலிருந்து நீங்கள் அதிகம் கற்றுக்கொள்ளலாம்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0021","en":"As long as an opening is reputed to be weak it can be played.","ta":"ஒரு தொடக்க ஆட்டம் பலவீனமானது என்று பெயர் பெற்றிருக்கும் வரை அதை விளையாடலாம்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0050","en":"Chess is life.","ta":"சதுரங்கமே வாழ்க்கை.","author":"Bobby Fischer","v":true},
  {"id":"Q0289","en":"The pawn is the soul of chess because it defines the struggle for space.","ta":"சிப்பாயே சதுரங்கத்தின் ஆன்மா; ஏனெனில் இடத்துக்கான போராட்டத்தை அது வரையறுக்கிறது.","author":"Philidor's Heirs","v":true},
  {"id":"Q0072","en":"Fischer, of course, is Fischer, but a knight is a knight.","ta":"ஃபிஷர் ஃபிஷர்தான்; ஆனால் குதிரை என்பது குதிரைதான்.","author":"Mikhail Tal","v":true},
  {"id":"Q0307","en":"The best chess player is the one who makes the fewest errors.","ta":"மிகக் குறைவான பிழைகளைச் செய்பவனே சிறந்த சதுரங்க வீரன்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0109","en":"Chess is so inspiring that I do not believe a good player is capable of having an evil thought during the game.","ta":"சதுரங்கம் மிகவும் ஊக்கமளிப்பது; ஆட்டத்தின்போது ஒரு நல்ல வீரனுக்குத் தீய எண்ணம்கூட வரும் என்று நான் நம்பவில்லை.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0240","en":"Every piece is a liability if it is placed wrongly.","ta":"தவறாக வைக்கப்பட்டால் ஒவ்வொரு காயும் ஒரு சுமையே.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0297","en":"The nimzo, the slav, the spanish all begin with the same idea: control the center.","ta":"நிம்சோ, ஸ்லாவ், ஸ்பானிஷ் எல்லாமே ஒரே கருத்துடன்தான் தொடங்குகின்றன: மையத்தைக் கட்டுப்படுத்துங்கள்.","author":"Mikhail Tal","v":true},
  {"id":"Q0224","en":"Chess is a game that you can learn in minutes and master in a lifetime.","ta":"சில நிமிடங்களில் கற்கக்கூடியதும், வாழ்நாள் முழுவதும் தேர்ச்சி பெற வேண்டியதுமான விளையாட்டு சதுரங்கம்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0318","en":"The best way to understand chess is to play it with love.","ta":"சதுரங்கத்தைப் புரிந்துகொள்வதற்கான சிறந்த வழி அதை அன்புடன் விளையாடுவதே.","author":"Emanuel Lasker","v":true},
  {"id":"Q0334","en":"Chess is the mind's gym, the soul's exercise.","ta":"மனதின் உடற்பயிற்சிக் கூடம், ஆன்மாவின் பயிற்சி சதுரங்கம்.","author":"Anatoly Karpov","v":true},
  {"id":"Q0155","en":"The essence of chess is thinking about what chess is.","ta":"சதுரங்கத்தின் சாரம் என்பது சதுரங்கம் என்றால் என்ன என்று சிந்திப்பதே.","author":"David Bronstein","v":true},
  {"id":"Q0055","en":"It is just you and your opponent at the board, and you are trying to prove something.","ta":"பலகையில் நீங்களும் உங்கள் எதிரியும் மட்டுமே; நீங்கள் ஏதோ ஒன்றை நிரூபிக்க முயல்கிறீர்கள்.","author":"Bobby Fischer","v":true},
  {"id":"Q0222","en":"All chess players know that a strong player is one who can see the board clearly, one who can separate the important from the unimportant.","ta":"பலமான வீரன் என்பவன் பலகையைத் தெளிவாகக் காண்பவன், முக்கியத்தை அமுக்கியத்திலிருந்து பிரிக்கத் தெரிந்தவன் என்று எல்லாச் சதுரங்க வீரர்களும் அறிவார்கள்.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0088","en":"During a chess competition, a chessmaster must be a combination of a beast of prey and a monk.","ta":"சதுரங்கப் போட்டியின்போது ஒரு மாஸ்டர், இரைவேட்டை விலங்கும் துறவியும் கலந்த ஒருவராக இருக்க வேண்டும்.","author":"Alexander Alekhine"},
  {"id":"Q0305","en":"The king is the soul of the endgame, just as the pawn is the soul of the opening.","ta":"சிப்பாய் தொடக்க ஆட்டத்தின் ஆன்மா என்றால், அரசன் இறுதி ஆட்டத்தின் ஆன்மா.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0097","en":"First restrain, then blockade, and finally destroy.","ta":"முதலில் அடக்குங்கள், பின்னர் முற்றுகையிடுங்கள், இறுதியில் ஒழித்துக்கட்டுங்கள்.","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0083","en":"Chess is mental torture.","ta":"சதுரங்கம் மனதை வதைக்கும் கொடுமை.","author":"Garry Kasparov","v":true},
  {"id":"Q0100","en":"The technique of positional play can be acquired.","ta":"நிலைப்பாட்டு விளையாட்டின் நுட்பத்தைப் பயிற்சியால் பெற முடியும்.","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0102","en":"Chess, like love, like music, has the power to make men happy.","ta":"அன்பைப் போலவும் இசையைப் போலவும், மனிதர்களை மகிழ்விக்கும் சக்தி சதுரங்கத்துக்கும் உண்டு.","author":"Siegbert Tarrasch"},
  {"id":"Q0148","en":"In chess, at least, the weights do not lie. You either calculate, or you do not.","ta":"குறைந்தபட்சம் சதுரங்கத்திலாவது எடைகள் பொய் சொல்வதில்லை. நீங்கள் கணக்கிடுகிறீர்கள், இல்லையென்றால் இல்லை.","author":"Magnus Carlsen","v":true},
  {"id":"Q0255","en":"Endgames are long, but their lessons last forever.","ta":"இறுதி ஆட்டங்கள் நீளமானவை; ஆனால் அவற்றின் பாடங்கள் என்றென்றும் நிலைக்கும்.","author":"C.J.S. Purdy","v":true},
  {"id":"Q0046","en":"You can only get good at chess if you love the game.","ta":"விளையாட்டை நேசித்தால்தான் சதுரங்கத்தில் சிறப்படைய முடியும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0344","en":"Chess is a game of quiet power and silent strength.","ta":"அமைதியான ஆற்றலும் மௌனமான உறுதியும் நிறைந்த விளையாட்டு சதுரங்கம்.","author":"Tigran Petrosian","v":true},
  {"id":"Q0214","en":"Knowing the endgame is knowing chess.","ta":"முடிவாட்டத்தை அறிவதுதான் சதுரங்கத்தை அறிவது.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0139","en":"I did not picture myself as even a grandmaster. The grandmasters existed in a completely different world; they were like gods or mythical heroes.","ta":"நான் ஒரு கிராண்ட் மாஸ்டர் என்றுகூட நினைத்ததில்லை. கிராண்ட் மாஸ்டர்கள் முற்றிலும் வேறு ஒரு உலகில் வாழ்ந்தனர்; அவர்கள் கடவுளர்களோ புராண நாயகர்களோ போலத் தெரிந்தனர்.","author":"Anatoly Karpov","v":true},
  {"id":"Q0132","en":"Chess is a beautiful mistress.","ta":"சதுரங்கம் அழகான ஒரு காதலி.","author":"Bent Larsen","v":true},
  {"id":"Q0186","en":"Without technique it is not possible to reach the zenith of chess, and so we all try to borrow from Capablanca that marvellous and subtle technique of his.","ta":"நுட்பம் இல்லாமல் சதுரங்கத்தின் உச்சியை அடைய முடியாது; அதனால் காபாபிளாங்காவின் அந்த அற்புதமான நுட்பமான ஆட்டமுறையை நாம் அனைவருமே உள்வாங்க முயல்கிறோம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0020","en":"Stalemate is the tragicomedy of chess.","ta":"முட்டுச்சந்திப்பு என்பது சதுரங்கத்தின் சோகநகைச்சுவை.","author":"Savielly Tartakower","v":true},
  {"id":"Q0220","en":"The middlegame is where the game is won or lost, and it is there that players decide their fate.","ta":"நடு ஆட்டத்தில்தான் ஆட்டம் வெல்லப்படுகிறதோ தோற்கப்படுகிறதோ; வீரர்கள் தம் கதியை அங்கேயே முடிவு செய்கிறார்கள்.","author":"Efim Geller","v":true},
  {"id":"Q0296","en":"In chess you must take your time; the board never hurries.","ta":"சதுரங்கத்தில் உங்கள் நேரத்தை எடுத்துக்கொள்ளுங்கள்; பலகை ஒருபோதும் அவசரப்படாது.","author":"Aaron Nimzowitsch","v":true},
  {"id":"Q0332","en":"The art of chess is the art of planning.","ta":"திட்டமிடுதலின் கலையே சதுரங்கக் கலை.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0204","en":"Strategy is the art of fighting a battle with pieces.","ta":"ஆட்டத் திட்டம் என்பது காய்களுடன் போர் நடத்தும் கலை.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0229","en":"The winner is the one who makes the fewest mistakes.","ta":"குறைவான தவறுகளைச் செய்பவனே வெற்றியாளன்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0283","en":"Chess is a game of small advantages accumulated over time.","ta":"காலப்போக்கில் குவியும் சிறிய நன்மைகளின் விளையாட்டு சதுரங்கம்.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0117","en":"Strategy requires thought; tactics require observation.","ta":"ஆட்டத் திட்டம் சிந்தனையைக் கோருகிறது; தந்திர நகர்வுகள் கவனிப்பைக் கோருகின்றன.","author":"Max Euwe","v":true},
  {"id":"Q0341","en":"Chess is a treasure hunt for the best move.","ta":"சிறந்த நகர்வுக்கான புதையல் தேடலே சதுரங்கம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0304","en":"Chess is a game of intellect, not of impulse.","ta":"தூண்டுதலின் விளையாட்டு அல்ல; அறிவாற்றலின் விளையாட்டு சதுரங்கம்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0017","en":"A master can sometimes play badly, but a fan never!","ta":"ஒரு மாஸ்டர் சில சமயம் மோசமாக விளையாடலாம்; ஆனால் ஒரு ரசிகன் ஒருபோதும் மோசமாக விளையாட மாட்டான்!","author":"Savielly Tartakower","v":true},
  {"id":"Q0194","en":"There are more adventures on a chessboard than on all the seas of the world.","ta":"உலகின் எல்லாக் கடல்களையும்விட ஒரு சதுரங்கப் பலகையிலேயே அதிக சாகசங்கள் நடக்கின்றன.","author":"Savielly Tartakower","v":true},
  {"id":"Q0064","en":"I would rather be free in my mind, and be locked up in a prison cell, than be a coward and not be able to say what I want.","ta":"கோழையாக இருந்து எனக்கு வேண்டியதைச் சொல்ல முடியாத நிலையைவிட, மனதில் சுதந்திரமாக இருந்துகொண்டே ஒரு சிறை அறையில் அடைக்கப்படுவதையே விரும்புகிறேன்.","author":"Bobby Fischer","v":true},
  {"id":"Q0225","en":"The best way to learn chess is to play, lose, and learn from your mistakes.","ta":"சதுரங்கம் கற்கச் சிறந்த வழி, விளையாடி, தோற்று, உங்கள் தவறுகளிலிருந்து கற்றுக்கொள்வதே.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0146","en":"In blitz, the weights change: intuition takes over from calculation.","ta":"பிளிட்ஸில் எடைகள் மாறுகின்றன: கணக்கிடுவதிலிருந்து உள்ளுணர்வு கையைப் பிடிக்கிறது.","author":"Magnus Carlsen","v":true},
  {"id":"Q0126","en":"If your opponent offers you a draw, try to work out why he thinks he is worse off.","ta":"எதிரி உங்களுக்குச் சமநிலை வழங்கினால், தான் பின்தங்கியிருப்பதாக அவன் ஏன் நினைக்கிறான் என்பதைக் கண்டறிய முயலுங்கள்.","author":"Nigel Short","v":true},
  {"id":"Q0154","en":"Chess is imagination.","ta":"சதுரங்கம் கற்பனை.","author":"David Bronstein","v":true},
  {"id":"Q0239","en":"When you find a good move, look for a better one.","ta":"நல்ல நகர்வு ஒன்று கண்டால், அதைவிடச் சிறந்ததைத் தேடுங்கள்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0013","en":"The winner of the game is the player who makes the next-to-last mistake.","ta":"இறுதிக்கு முந்தைய தவறைச் செய்பவனே ஆட்டத்தின் வெற்றியாளன்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0175","en":"A single exposure to chess is apt to make an addict of anyone with a sense of adventure.","ta":"சதுரங்கத்திற்கு ஒரு முறை பழகினாலே, சாகச உணர்வுள்ள எவரையும் அது அடிமையாக்கிவிடும்.","author":"Edward Lasker","v":true},
  {"id":"Q0286","en":"A well-played chess game is a work of art.","ta":"நன்கு விளையாடப்பட்ட ஒரு சதுரங்க ஆட்டம் ஒரு கலைப்படைப்பு.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0314","en":"The hardest battles in chess are fought in the endgame.","ta":"சதுரங்கத்தின் மிகக் கடினமான போர்கள் இறுதி ஆட்டத்தில்தான் நடக்கின்றன.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0250","en":"The advantage is a great thing to have, but most players do not know how to convert it.","ta":"நன்மையைக் கொண்டிருப்பது மிகச் சிறந்தது; ஆனால் அதை எப்படி வெற்றியாக மாற்றுவது என்று பல வீரர்களுக்குத் தெரியாது.","author":"Bobby Fischer","v":true},
  {"id":"Q0129","en":"Chess is a game by its form, an art by its content, and a science by the difficulty of gaining mastery in it.","ta":"வடிவத்தால் சதுரங்கம் ஒரு விளையாட்டு; உள்ளடக்கத்தால் ஒரு கலை; அதில் தேர்ச்சி பெறுவதன் கடினத்தால் ஒரு அறிவியல்.","author":"Tigran Petrosian"},
  {"id":"Q0019","en":"A game of chess has three phases: the opening, where you hope you stand better; the middlegame, where you think you stand better; and the ending, where you know you stand to lose.","ta":"சதுரங்க ஆட்டத்திற்கு மூன்று கட்டங்கள்: துவக்கம் — நீங்கள் நன்றாக இருக்கிறீர்கள் என்று நம்பும் கட்டம்; நடுஆட்டம் — நன்றாக இருக்கிறீர்கள் என்று நினைக்கும் கட்டம்; முடிவாட்டம் — தோற்கப் போகிறீர்கள் என்று உறுதியாகத் தெரியும் கட்டம்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0213","en":"You don't have to play well to win; you just have to play better than your opponent.","ta":"வெல்ல நன்றாக விளையாட வேண்டியதில்லை; உங்கள் எதிரியைவிடச் சிறப்பாக விளையாடினால் போதும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0056","en":"I give ninety-eight percent of my mental energy to chess; others give only two percent.","ta":"என் மன ஆற்றலில் தொண்ணூற்று எட்டு சதவீதத்தை சதுரங்கத்திற்குத் தருகிறேன்; மற்றவர்கள் இரண்டு சதவீதமே தருகிறார்கள்.","author":"Bobby Fischer","v":true},
  {"id":"Q0011","en":"It is always better to sacrifice your opponent's men.","ta":"எதிரியின் காய்களைத் தியாகம் செய்வதே எப்போதும் சிறந்தது.","author":"Savielly Tartakower","v":true},
  {"id":"Q0276","en":"Chess is the game that teaches you to think before you act.","ta":"செயல்படுவதற்கு முன் சிந்திக்கக் கற்பிக்கும் விளையாட்டு சதுரங்கம்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0093","en":"We cannot resist the fascination of sacrifice, since a passion for sacrifices is part of a chess player's nature.","ta":"தியாகத்தின் மீதான கவர்ச்சியை நம்மால் எதிர்க்க முடியாது; ஏனெனில் தியாகங்களின் மீதான பேரார்வம் சதுரங்க வீரனின் இயல்பின் ஒரு பகுதி.","author":"Rudolf Spielmann","v":true},
  {"id":"Q0269","en":"Give me the right move and I will show you a winning game.","ta":"சரியான நகர்வை எனக்குக் கொடுங்கள்; வெற்றி பெறும் ஆட்டத்தைக் காட்டுகிறேன்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0277","en":"The first move is the beginning of a thousand possibilities.","ta":"முதல் நகர்வே ஆயிரம் சாத்தியங்களின் தொடக்கம்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0039","en":"All that matters on the chessboard is good moves.","ta":"சதுரங்கப் பலகையில் முக்கியமானது நல்ல நகர்வுகள் மட்டுமே.","author":"Bobby Fischer","v":true},
  {"id":"Q0209","en":"Passed pawns must be pushed.","ta":"வழியைத் தாண்டிய சிப்பாய்களை முன்னே தள்ளியே ஆக வேண்டும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0185","en":"After the game, Fischer calmly remarked that he had already analysed this possibility.","ta":"ஆட்டத்துக்குப் பின்னர், இந்தச் சாத்தியத்தைத் தான் ஏற்கனவே பகுப்பாய்வு செய்துவிட்டதாக ஃபிஷர் அமைதியாகக் குறிப்பிட்டார்.","author":"Mikhail Tal","v":true},
  {"id":"Q0113","en":"I have never in my life played the French Defence, which is the dullest of all openings.","ta":"எல்லாத் தொடக்க ஆட்டங்களிலும் மிகச் சப்பையான ஃப்ரெஞ்ச் பாதுகாப்பை என் வாழ்வில் ஒருமுறைகூட விளையாடியதில்லை.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0054","en":"Psychologically, you have to have confidence in yourself, and this confidence should be based on fact.","ta":"உளவியல் அடிப்படையில், உங்கள்மீது உங்களுக்கு நம்பிக்கை இருக்க வேண்டும்; அந்த நம்பிக்கை உண்மையின் அடிப்படையில் அமைந்திருக்க வேண்டும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0040","en":"Chess is a matter of delicate judgement, knowing when to punch and how to duck.","ta":"சதுரங்கம் நுட்பமான மதிப்பீட்டின் விஷயம்; எப்போது குத்துவது, எப்படி நழுவுவது என்று அறிவது.","author":"Bobby Fischer","v":true},
  {"id":"Q0275","en":"A chess game is a dialogue between two minds.","ta":"சதுரங்க ஆட்டம் இரு மனங்களுக்கு இடையிலான உரையாடல்.","author":"Lasker","v":true},
  {"id":"Q0170","en":"Chess teaches foresight, by having to plan ahead.","ta":"முன்கூட்டியே திட்டமிட வேண்டியிருப்பதால், சதுரங்கம் முன்னறிவைக் கற்பிக்கிறது.","author":"Benjamin Franklin","v":true},
  {"id":"Q0287","en":"Never play a move without understanding why you play it.","ta":"ஏன் விளையாடுகிறோம் என்று புரிந்துகொள்ளாமல் ஒருபோதும் ஒரு நகர்வை விளையாடாதீர்கள்.","author":"Frank Marshall","v":true},
  {"id":"Q0282","en":"Chess is the most honest game: it reveals exactly who you are.","ta":"மிக நேர்மையான விளையாட்டு சதுரங்கம்; நீங்கள் யார் என்பதை அது சரியாக வெளிப்படுத்துகிறது.","author":"Mikhail Tal","v":true},
  {"id":"Q0365","en":"The purpose of the game is to avoid defeat, and winning is only a means to that end.","ta":"ஆட்டத்தின் நோக்கம் தோல்வியைத் தவிர்ப்பதே; வெற்றி என்பது அந்த நோக்கத்தை அடைய ஒரு வழி மட்டுமே.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0303","en":"A good chess player anticipates his opponent's plans.","ta":"நல்ல சதுரங்க வீரன் எதிரியின் திட்டங்களை முன்கூட்டியே ஊகிக்கிறான்.","author":"Frank Marshall","v":true},
  {"id":"Q0161","en":"Capablanca was the best, because he did not need to bother.","ta":"சிறந்தவர் காபாபிளாங்காவே; ஏனெனில் அவர் அதற்காகச் சிரமப்பட வேண்டியிருக்கவில்லை.","author":"Miguel Najdorf","v":true},
  {"id":"Q0339","en":"Chess is the great equalizer: on the board, all are equal.","ta":"சதுரங்கமே மாபெரும் சமநிலைப்படுத்தி; பலகையில் அனைவரும் சமமே.","author":"Savielly Tartakower","v":true},
  {"id":"Q0067","en":"I have always had the feeling that combinations are the very beauty of chess.","ta":"சேர்க்கை நகர்வுகள்தான் சதுரங்கத்தின் உண்மையான அழகு என்று நான் எப்போதும் உணர்ந்திருக்கிறேன்.","author":"Mikhail Tal"},
  {"id":"Q0352","en":"Chess is the training ground for the mind.","ta":"மனதின் பயிற்சிக் களம் சதுரங்கம்.","author":"Anatoly Karpov","v":true},
  {"id":"Q0140","en":"Chess is not for the faint-hearted; it absorbs a person entirely.","ta":"சதுரங்கம் துவளும் மனதினருக்கானது அல்ல; அது ஒரு மனிதனை முழுமையாகத் தன்னுள் உள்வாங்கிக்கொள்கிறது.","author":"Vladimir Kramnik","v":true},
  {"id":"Q0078","en":"Chess is the art of analysis.","ta":"சதுரங்கம் பகுப்பாய்வின் கலை.","author":"Garry Kasparov"},
  {"id":"Q0232","en":"Chess is a battle between the two minds, a war of ideas.","ta":"சதுரங்கம் இரு மனங்களுக்கு இடையிலான சண்டை, சிந்தனைகளின் யுத்தம்.","author":"Reuben Fine","v":true},
  {"id":"Q0356","en":"Chess is a game of balance; every piece must find its place.","ta":"சமநிலையின் விளையாட்டு சதுரங்கம்; ஒவ்வொரு காயும் அதற்கான இடத்தைக் கண்டடைய வேண்டும்.","author":"Aaron Nimzowitsch","v":true},
  {"id":"Q0014","en":"An isolated pawn spreads gloom all over the chessboard.","ta":"தனிமையில் இருக்கும் சிப்பாய், சதுரங்கப் பலகை முழுவதும் சோகத்தைப் பரப்புகிறது.","author":"Savielly Tartakower","v":true},
  {"id":"Q0074","en":"Of course, errors are not good for a chess game, but errors are unavoidable, and in any case a game without errors, the so-called flawless game, is colorless.","ta":"நிச்சயமாக, சதுரங்க ஆட்டத்திற்குத் தவறுகள் நல்லதல்ல; ஆனால் அவை தவிர்க்க முடியாதவை. எப்படியிருந்தாலும், தவறுகள் இல்லாத — 'குறையற்ற' எனப்படும் — ஆட்டம் நிறமற்றதே.","author":"Mikhail Tal","v":true},
  {"id":"Q0103","en":"Before the endgame, the gods have placed the middlegame.","ta":"இறுதி ஆட்டத்துக்கு முன்பாக, கடவுளர்கள் நடு ஆட்டத்தையே வைத்திருக்கிறார்கள்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0115","en":"He is the greatest artist amongst chess players.","ta":"சதுரங்க வீரர்களிலேயே மிகப் பெரிய கலைஞன் அவரே.","author":"Richard Réti","v":true},
  {"id":"Q0008","en":"The blunders are all there on the board, waiting to be made.","ta":"தவறுகள் எல்லாம் பலகையிலேயே இருக்கின்றன, செய்யப்படுவதற்காகக் காத்திருக்கின்றன.","author":"Savielly Tartakower"},
  {"id":"Q0183","en":"The opening is the only phase that holds out the potential for true creativity and doing something entirely new.","ta":"உண்மையான படைப்பாற்றலுக்கும், முற்றிலும் புதிய ஒன்றைச் செய்யும் வாய்ப்புக்கும் இடம் தரும் ஒரே கட்டம் தொடக்க ஆட்டம்தான்.","author":"Garry Kasparov","v":true},
  {"id":"Q0247","en":"Chess is not for the faint-hearted.","ta":"சதுரங்கம் துவளும் மனதினருக்கானது அல்ல.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0131","en":"Emotional instability can be one of the factors giving rise to a change in the character of the game.","ta":"உணர்ச்சிக் கொந்தளிப்பு, ஆட்டத்தின் தன்மையை மாற்றும் காரணிகளில் ஒன்றாக இருக்கலாம்.","author":"Tigran Petrosian","v":true},
  {"id":"Q0141","en":"I am convinced that the way one plays chess always reflects the player's personality.","ta":"ஒருவர் சதுரங்கம் விளையாடும் முறை, எப்போதும் அவரது ஆளுமையையே பிரதிபலிக்கும் என்று நான் நம்புகிறேன்.","author":"Vladimir Kramnik","v":true},
  {"id":"Q0025","en":"You may learn much more from a game you lose than from a game you win. You will have to lose hundreds of games before becoming a good player.","ta":"வென்ற ஆட்டத்தைவிட, தோற்ற ஆட்டத்திலிருந்து அதிகம் கற்றுக்கொள்ளலாம். ஒரு நல்ல வீரன் ஆவதற்கு முன் நூற்றுக்கணக்கான ஆட்டங்களில் தோற்க வேண்டியிருக்கும்.","author":"José Raúl Capablanca"},
  {"id":"Q0062","en":"Someday computers will make us all obsolete.","ta":"ஒரு நாள் கணினிகள் நம் அனைவரையும் தேவையற்றவர்களாக ஆக்கிவிடும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0188","en":"Too many times, people do not try their best. They do not have the keen spirit, the winning spirit. And once you make it, you have got to guard your reputation - every day go in like an unknown to prove yourself.","ta":"பல நேரங்களில் மக்கள் தங்களால் முடிந்ததைச் செய்வதில்லை. அவர்களிடம் தீவிர உணர்வும், வெற்றி மனப்பான்மையும் இல்லை. ஒருமுறை வெற்றி பெற்றுவிட்டால், உங்கள் புகழைக் காக்க வேண்டும் — தினமும் அடையாளம் தெரியாதவர் போலவே இறங்கி உங்களை நிரூபிக்க வேண்டும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0273","en":"Space is time in chess; control of squares is control of the game.","ta":"சதுரங்கத்தில் இடமே நேரம்; சதுரங்களின் கட்டுப்பாடே ஆட்டத்தின் கட்டுப்பாடு.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0169","en":"Life is a kind of chess.","ta":"வாழ்க்கை ஒருவித சதுரங்கம்.","author":"Benjamin Franklin","v":true},
  {"id":"Q0086","en":"When your house is on fire, you cannot be bothered with the neighbours. As we say in chess, if your king is under attack, do not worry about losing a pawn on the queenside.","ta":"உங்கள் வீட்டில் தீப்பற்றியிருக்கும்போது, அண்டை வீட்டாரைப் பற்றிக் கவலைப்பட முடியாது. சதுரங்கத்தில் சொல்வதுபோல, உங்கள் அரசன் தாக்குதலில் இருந்தால், அரசியின் பக்கம் ஒரு சிப்பாயை இழப்பதைப் பற்றிக் கவலைப்படாதீர்கள்.","author":"Garry Kasparov","v":true},
  {"id":"Q0006","en":"Get the knights into action before both bishops are developed.","ta":"இரு மந்திரிகளும் வளர்ந்தெழுவதற்கு முன்பே குதிரைகளைச் செயலில் இறக்குங்கள்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0134","en":"In chess, as in life, a man is his own most dangerous opponent.","ta":"சதுரங்கத்திலும் வாழ்க்கையிலும், மனிதனுக்கு மிக ஆபத்தான எதிரி அவனேதான்.","author":"Vasily Smyslov","v":true},
  {"id":"Q0059","en":"I have never opened with the queen's pawn, on principle.","ta":"கொள்கையின் அடிப்படையில், நான் ஒருபோதும் அரசியின் சிப்பாயுடன் தொடங்கியதில்லை.","author":"Bobby Fischer","v":true},
  {"id":"Q0084","en":"In chess, bigamy is acceptable, but monarchy is absolute.","ta":"சதுரங்கத்தில் இருதாரம் ஏற்கத்தக்கது; ஆனால் முடியாட்சி முழுமையானது.","author":"Garry Kasparov","v":true},
  {"id":"Q0178","en":"Chess transcends language, age, race, religion, politics, gender and socio-economic background. Whatever your circumstances, anyone can enjoy a good fight to the death over the chessboard.","ta":"சதுரங்கம் மொழி, வயது, இனம், மதம், அரசியல், பாலினம், சமூகப் பொருளாதாரப் பின்னணி ஆகிய அனைத்தையும் கடந்தது. உங்கள் சூழல் எதுவாக இருந்தாலும், சதுரங்கப் பலகையில் இறுதிவரை நடக்கும் ஒரு நல்ல போராட்டத்தை எவரும் அனுபவிக்கலாம்.","author":"Simon Williams","v":true},
  {"id":"Q0066","en":"You must take your opponent into a deep dark forest where 2+2=5, and the path leading out is only wide enough for one.","ta":"2+2=5 ஆகிவிடும் ஒரு ஆழமான இருண்ட காட்டுக்குள் உங்கள் எதிரியை அழைத்துச் செல்ல வேண்டும்; அங்கிருந்து மீளும் பாதை ஒருவருக்கு மட்டுமே போதுமான அளவுக்குக் குறுகியதாக இருக்கும்.","author":"Mikhail Tal"},
  {"id":"Q0162","en":"When Tal sacrifices a piece, it is worth checking why; when Petrosian makes a sacrifice, it is worth conceding.","ta":"டால் ஒரு காயைத் தியாகம் செய்தால், ஏன் எனப் பார்ப்பது மதிப்புள்ளது; பெட்ரோசியன் ஒரு தியாகம் செய்தால், அதை ஏற்றுக்கொள்வது மதிப்புள்ளது.","author":"Miguel Najdorf","v":true},
  {"id":"Q0267","en":"The beauty of chess is that it requires constant learning.","ta":"தொடர்ந்து கற்றுக்கொண்டே இருக்க வேண்டும் என்பதே சதுரங்கத்தின் அழகு.","author":"Bobby Fischer","v":true},
  {"id":"Q0049","en":"All I want to do, ever, is just play chess.","ta":"நான் எப்போதும் செய்ய விரும்புவதெல்லாம், வெறுமனே சதுரங்கம் விளையாடுவதுதான்.","author":"Bobby Fischer","v":true},
  {"id":"Q0192","en":"I prefer to lose a really good game than to win a bad one.","ta":"மோசமான ஒரு ஆட்டத்தை வெல்வதைவிட, உண்மையிலேயே நல்ல ஒரு ஆட்டத்தில் தோற்பதையே விரும்புகிறேன்.","author":"David Levy","v":true},
  {"id":"Q0311","en":"A pawn chain is a wall that shapes the whole game.","ta":"சிப்பாய்ச் சங்கிலி என்பது முழு ஆட்டத்தையும் வடிவமைக்கும் ஒரு சுவர்.","author":"Aaron Nimzowitsch","v":true},
  {"id":"Q0166","en":"It is not a move, even the best move, that you must seek, but a realizable plan.","ta":"நீங்கள் தேட வேண்டியது ஒரு நகர்வை அல்ல — சிறந்த நகர்வைக்கூட அல்ல — நிறைவேற்றக்கூடிய ஒரு திட்டத்தைத்தான்.","author":"Eugene Znosko-Borovsky","v":true},
  {"id":"Q0007","en":"The game gives us a satisfaction that life denies us; and for the chess player, the success that crowns his work, the great dispeller of sorrows, is named combination.","ta":"வாழ்க்கை நமக்கு மறுக்கும் திருப்தியை ஆட்டம் நமக்குத் தருகிறது; ஒரு சதுரங்க வீரனுக்கு, அவனது உழைப்புக்குக் கிரீடம் சூட்டும் வெற்றி — துயரங்களை விரட்டும் அந்தப் பெருஞ்சக்தி — சேர்க்கை நகர்வு எனப்படுகிறது.","author":"Emanuel Lasker","v":true},
  {"id":"Q0223","en":"To play chess well you must first learn to lose gracefully.","ta":"சதுரங்கத்தை நன்றாக விளையாட, முதலில் கண்ணியமாகத் தோற்கக் கற்றுக்கொள்ள வேண்டும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0110","en":"A sacrifice is best refuted by accepting it.","ta":"ஒரு தியாகத்தை மறுப்பதற்குச் சிறந்த வழி, அதை ஏற்றுக்கொள்வதே.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0150","en":"When I am White, I win because I am White. When I am Black, I win because I am Bogoljubov.","ta":"நான் வெள்ளையாக இருக்கும்போது வெல்கிறேன், ஏனெனில் நான் வெள்ளை. கருப்பாக இருக்கும்போது வெல்கிறேன், ஏனெனில் நான் போகொல்யுபோவ்.","author":"Efim Bogoljubov","v":true},
  {"id":"Q0068","en":"There are two types of sacrifices: correct ones, and mine.","ta":"தியாகங்கள் இரண்டு வகைப்படும்: சரியானவை, மற்றும் என்னுடையவை.","author":"Mikhail Tal","v":true},
  {"id":"Q0099","en":"A crushing position in the centre grants the right to attack on the wing.","ta":"மையத்தில் உள்ள நசுக்கும் நிலை, பக்கவாட்டில் தாக்கும் உரிமையை வழங்குகிறது.","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0153","en":"The most powerful weapon in chess is to have the next move.","ta":"சதுரங்கத்தில் மிக சக்திவாய்ந்த ஆயுதம், அடுத்த நகர்வு உங்கள் கையில் இருப்பதே.","author":"David Bronstein","v":true},
  {"id":"Q0338","en":"Chess is a game of mirrors; the opponent reflects your own flaws.","ta":"சதுரங்கம் கண்ணாடிகளின் விளையாட்டு; எதிரி உங்கள் சொந்தக் குறைகளையே பிரதிபலிக்கிறான்.","author":"Nikolai Krogius","v":true},
  {"id":"Q0218","en":"Chess is a war over the board. The object is to crush the opponent's mind.","ta":"சதுரங்கம் பலகை மீதான போர். எதிரியின் மனதை நொறுக்குவதே நோக்கம்.","author":"Bobby Fischer","v":true},
  {"id":"Q0156","en":"Critical positions, more than anything else, reveal a player's true qualities.","ta":"முக்கியமான நிலைகள்தான், எதையும்விட, ஒரு வீரனின் உண்மையான குணங்களை வெளிப்படுத்துகின்றன.","author":"David Bronstein","v":true},
  {"id":"Q0272","en":"In chess, the strongest weapon is a clear head.","ta":"சதுரங்கத்தில் மிக வலுவான ஆயுதம் தெளிவான மனமே.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0306","en":"Chess is a very precise game; it is the game of science and art at once.","ta":"மிகத் துல்லியமான விளையாட்டு சதுரங்கம்; அது ஒரே நேரத்தில் அறிவியலும் கலையும்.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0048","en":"Your body has to be in top condition. Your chess deteriorates as your body does.","ta":"உங்கள் உடல் உச்ச நிலையில் இருக்க வேண்டும். உடல் தேயும்போது உங்கள் சதுரங்கமும் தேய்கிறது.","author":"Bobby Fischer","v":true},
  {"id":"Q0075","en":"The cherished dream of every chess player is to play a match with the world champion; and the paradox is that the closer you come to this goal, the less you think about it.","ta":"ஒவ்வொரு சதுரங்க வீரனின் மனதில் நிறைந்த கனவு உலக சாம்பியனுடன் ஒரு ஆட்டம் ஆடுவதே; ஆனால் விந்தை என்னவென்றால், அந்த இலக்கை நெருங்க நெருங்க அதைப் பற்றி நீங்கள் குறைவாகவே நினைக்கிறீர்கள்.","author":"Mikhail Tal","v":true},
  {"id":"Q0197","en":"Chess is the gymnasium of the mind.","ta":"மனதின் உடற்பயிற்சிக் கூடம் சதுரங்கம்.","author":"Vasily Panov","v":true},
  {"id":"Q0238","en":"The best defense is a good attack.","ta":"சிறந்த தற்காப்பு ஒரு நல்ல தாக்குதலே.","author":"Savielly Tartakower","v":true},
  {"id":"Q0249","en":"Castle early and often.","ta":"விரைவாகவும் அடிக்கடியும் கோட்டை குடியேற்றம் செய்யுங்கள்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0143","en":"Chess helps you to concentrate, to improve your logic.","ta":"செறிவடையவும், உங்கள் தர்க்கத்தை மேம்படுத்தவும் சதுரங்கம் உதவுகிறது.","author":"Viswanathan Anand","v":true},
  {"id":"Q0164","en":"One bad move nullifies forty good ones.","ta":"ஒரு மோசமான நகர்வு நாற்பது நல்ல நகர்வுகளை வீணாக்கிவிடும்.","author":"Israel Albert Horowitz","v":true},
  {"id":"Q0101","en":"If I seize a bit of debatable land with a handful of soldiers, without having done anything to prevent an enemy bombardment of the position, why should I speak of a conquest of the terrain?","ta":"எதிரியின் குண்டுவீச்சைத் தடுக்க எதுவும் செய்யாமல், ஒரு கைப்பிடி வீரர்களுடன் ஒரு சர்ச்சைக்குரிய நிலப்பகுதியைப் பிடித்தால், அதை நான் ஏன் வெற்றி என்று சொல்ல வேண்டும்?","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0206","en":"The greatest joy in chess is the joy of discovery.","ta":"சதுரங்கத்தின் மிகப்பெரிய இன்பம் கண்டுபிடிப்பின் இன்பமே.","author":"John Nunn","v":true},
  {"id":"Q0308","en":"Chess is a game of total war, where the mind is the only weapon.","ta":"சதுரங்கம் முழுமையான போரின் விளையாட்டு; அதில் மனமே ஒரே ஆயுதம்.","author":"Viktor Korchnoi","v":true},
  {"id":"Q0005","en":"Without error there can be no brilliancy.","ta":"பிழை இல்லாமல் அற்புதம் இருக்க முடியாது.","author":"Emanuel Lasker","v":true},
  {"id":"Q0263","en":"In chess, the mind is the battlefield and the pieces are the soldiers.","ta":"சதுரங்கத்தில் மனமே போர்க்களம்; காய்களே படைவீரர்கள்.","author":"Capablanca","v":true},
  {"id":"Q0292","en":"In chess, the quiet moves often speak the loudest.","ta":"சதுரங்கத்தில் அமைதியான நகர்வுகளே அடிக்கடி மிக உரத்த குரலில் பேசுகின்றன.","author":"Tigran Petrosian","v":true},
  {"id":"Q0193","en":"To avoid losing a piece, many a person has lost the game.","ta":"ஒரு காயை இழக்காமல் தவிர்ப்பதற்காகப் பலர் ஆட்டத்தையே இழந்திருக்கிறார்கள்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0324","en":"Chess gives you the greatest freedom: the freedom to think.","ta":"சிந்திக்கும் சுதந்திரம் என்ற மிகப்பெரிய சுதந்திரத்தை சதுரங்கம் தருகிறது.","author":"Mikhail Tal","v":true},
  {"id":"Q0108","en":"He who fears an isolated queen's pawn should give up chess.","ta":"தனியாக இருக்கும் அரசி சிப்பாயைக் கண்டு பயப்படுபவர், சதுரங்கம் விளையாடுவதையே விட்டுவிடலாம்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0127","en":"Chess is like life.","ta":"சதுரங்கம் வாழ்க்கை போன்றது.","author":"Boris Spassky","v":true},
  {"id":"Q0128","en":"Playing against Fischer is dangerous. It is like playing with a loaded gun.","ta":"ஃபிஷருக்கு எதிராக விளையாடுவது ஆபத்தானது; அது குண்டு நிரப்பப்பட்ட துப்பாக்கியுடன் விளையாடுவது போன்றது.","author":"Boris Spassky","v":true},
  {"id":"Q0176","en":"Chess would be laughable, were it not so serious.","ta":"சதுரங்கம் இத்தனை தீவிரமானதாக இல்லாதிருந்தால், அது நகைப்புக்குரியதாக இருந்திருக்கும்.","author":"Edward Lasker","v":true},
  {"id":"Q0294","en":"One good pawn move can decide the fate of the whole game.","ta":"ஒரு நல்ல சிப்பாய் நகர்வு, முழு ஆட்டத்தின் தலைவிதியையே முடிவு செய்யும்.","author":"Emanuel Lasker","v":true},
  {"id":"Q0172","en":"It does not matter how strong a player you are; if you fail to register some development in the opening, then you are asking for trouble.","ta":"நீங்கள் எவ்வளவு பலமான வீரராக இருந்தாலும், தொடக்க ஆட்டத்தில் காய்களை வளர்த்தெடுக்கத் தவறினால், சிக்கலைத் தேடிக்கொள்கிறீர்கள்.","author":"John Emms","v":true},
  {"id":"Q0243","en":"The middle game is the heart of chess.","ta":"நடு ஆட்டமே சதுரங்கத்தின் இதயம்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0234","en":"A pawn is a bundle of dreams.","ta":"ஒரு சிப்பாய் என்பது கனவுகளின் கட்டு.","author":"C.J.S. Purdy","v":true},
  {"id":"Q0261","en":"Chess is the most beautiful game ever invented by man.","ta":"மனிதன் கண்டுபிடித்த மிக அழகான விளையாட்டு சதுரங்கம்.","author":"Jacques C. Schwarz","v":true},
  {"id":"Q0037","en":"1.e4 - best by test.","ta":"1.e4 — சோதித்துப் பார்த்ததில் சிறந்தது.","author":"Bobby Fischer","v":true},
  {"id":"Q0001","en":"The pawns are the soul of chess.","ta":"சிப்பாய்களே சதுரங்கத்தின் ஆன்மா.","author":"François-André Danican Philidor"},
  {"id":"Q0359","en":"The chess player's greatest enemy is himself.","ta":"சதுரங்க வீரனின் மிகப்பெரிய எதிரி அவனே.","author":"Viktor Korchnoi","v":true},
  {"id":"Q0142","en":"My style is somewhere between that of Tal and Petrosian.","ta":"என் ஆட்டப் பாணி டாலுக்கும் பெட்ரோசியனுக்கும் இடையில் எங்கோ இருக்கிறது.","author":"Viswanathan Anand","v":true},
  {"id":"Q0278","en":"Chess is a game of elegance and precision.","ta":"நேர்த்தியும் துல்லியமும் நிறைந்த விளையாட்டு சதுரங்கம்.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0028","en":"In order to improve your game, you must study the endgame before everything else.","ta":"உங்கள் ஆட்டத்தை மேம்படுத்த, எல்லாவற்றுக்கும் முன்பாக இறுதி ஆட்டத்தைப் படிக்க வேண்டும்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0335","en":"The chess player is a philosopher in action.","ta":"சதுரங்க வீரன் என்பவன் செயலில் இறங்கிய ஒரு தத்துவஞானி.","author":"Yuri Averbakh","v":true},
  {"id":"Q0047","en":"A strong memory, concentration, imagination, and a strong will are required to become a great chess player.","ta":"சிறந்த சதுரங்க வீரனாக மாற நினைவாற்றல், செறிவு, கற்பனை, வலுவான மனவுறுதி ஆகியவை தேவை.","author":"Bobby Fischer","v":true},
  {"id":"Q0251","en":"I play chess to win, not for fun.","ta":"வேடிக்கைக்காக அல்ல; வெல்லவே நான் சதுரங்கம் விளையாடுகிறேன்.","author":"Boris Spassky","v":true},
  {"id":"Q0076","en":"I have always thought it a matter of honour for every chess player to deserve the smile of fortune.","ta":"ஒவ்வொரு சதுரங்க வீரனும் அதிர்ஷ்டத்தின் புன்னகைக்குத் தகுதியானவனாக இருக்க வேண்டும் என்பதை நான் எப்போதும் ஒரு மானத்தின் விஷயமாகக் கருதியிருக்கிறேன்.","author":"Mikhail Tal","v":true},
  {"id":"Q0026","en":"A good player is always lucky.","ta":"நல்ல வீரன் எப்போதும் அதிர்ஷ்டசாலியே.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0313","en":"In chess, the queen is powerful but she cannot win alone.","ta":"சதுரங்கத்தில் அரசி ஆற்றல் மிக்கவள்; ஆனால் தனியே வெல்ல முடியாது.","author":"Capablanca","v":true},
  {"id":"Q0346","en":"Chess teaches us to respect our opponents and ourselves.","ta":"எதிரிகளையும் நம்மையும் மதிக்கக் கற்பிக்கிறது சதுரங்கம்.","author":"Anatoly Karpov","v":true},
  {"id":"Q0104","en":"It is not enough to be a good player; you must also play well.","ta":"நல்ல வீரனாக இருப்பது மட்டும் போதாது; நீங்கள் நன்றாக விளையாடவும் வேண்டும்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0321","en":"The rook is the castle, the king's shield in battle.","ta":"கோட்டைக் காய் என்பது அரசனின் கோட்டை; போரில் அவனது கேடயம்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0290","en":"Chess is the only game where you can defeat yourself.","ta":"உங்களையே நீங்களே தோற்கடிக்கக் கூடிய ஒரே விளையாட்டு சதுரங்கம்.","author":"Viktor Korchnoi","v":true},
  {"id":"Q0168","en":"The game of chess is not merely an idle amusement. Several very valuable qualities of the mind are to be acquired and strengthened by it, as foresight, circumspection and caution.","ta":"சதுரங்கம் வெறும் வேலையில்லாப் பொழுதுபோக்கு அல்ல. முன்னறிவு, நுட்பமான கவனம், எச்சரிக்கை போன்ற மனதின் மிகவும் விலைமதிப்புமிக்கப் பல குணங்களை அது கற்றுத் தருகிறது, வலுப்படுத்துகிறது.","author":"Benjamin Franklin"},
  {"id":"Q0024","en":"If chess is a struggle, the best is Lasker; if chess is science, the best is Capablanca; if chess is art, the best is Alekhine.","ta":"சதுரங்கம் போராட்டம் என்றால் சிறந்தவர் லாஸ்கர்; சதுரங்கம் அறிவியல் என்றால் சிறந்தவர் காபாபிளாங்கா; சதுரங்கம் கலை என்றால் சிறந்தவர் அலெகைன்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0227","en":"The board is the reflection of the mind; when the mind is clear, the play is clear.","ta":"பலகை மனதின் பிரதிபலிப்பு; மனம் தெளிவாக இருக்கும்போது ஆட்டமும் தெளிவாக இருக்கும்.","author":"Eugene Znosko-Borovsky","v":true},
  {"id":"Q0051","en":"That is what chess is all about. One day you give your opponent a lesson, the next day he gives you one.","ta":"சதுரங்கம் என்றால் இதுதான்: ஒரு நாள் நீங்கள் எதிரிக்கு ஒரு பாடம் சொல்லித் தருவீர்கள்; மறுநாள் அவர் உங்களுக்குச் சொல்லித் தருவார்.","author":"Bobby Fischer","v":true},
  {"id":"Q0043","en":"There are tough players and nice guys, and I am a tough player.","ta":"கடுமையான வீரர்களும் உண்டு, நல்ல மனிதர்களும் உண்டு; நான் கடுமையான வீரன்.","author":"Bobby Fischer","v":true},
  {"id":"Q0330","en":"Chess is the ultimate mental discipline.","ta":"சதுரங்கம் உச்சமான மனப் பயிற்சி.","author":"Yasser Seirawan","v":true},
  {"id":"Q0116","en":"Whoever sees no other aim in the game than that of giving checkmate to one's opponent will never become a good chess player.","ta":"எதிரிக்கு மாத் வைப்பதைத் தவிர வேறு நோக்கமே இல்லை என்பவன் ஒருபோதும் நல்ல சதுரங்க வீரனாக மாட்டான்.","author":"Max Euwe","v":true},
  {"id":"Q0257","en":"Chess is a game that requires a cool head.","ta":"குளிர்ந்த மனம் தேவைப்படும் விளையாட்டு சதுரங்கம்.","author":"Rubinstein","v":true},
  {"id":"Q0119","en":"Chess is the struggle against error.","ta":"சதுரங்கம் என்பது தவறுக்கு எதிரான போராட்டம்.","author":"Johannes Zukertort","v":true},
  {"id":"Q0003","en":"On the chessboard lies and hypocrisy do not survive long.","ta":"சதுரங்கப் பலகையில் பொய்யும் பாசாங்கும் நீண்ட நாள் உயிர்வாழாது.","author":"Emanuel Lasker"},
  {"id":"Q0045","en":"The turning point in my career came with the realization that Black should play to win instead of just steering for equality.","ta":"கருப்பு காய்களுடன் விளையாடுபவன் சமநிலைக்காக மட்டுமல்லாமல் வெற்றிக்காகவும் விளையாட வேண்டும் என்பதை உணர்ந்த போது, என் தொழில் வாழ்வின் திருப்புமுனை வந்தது.","author":"Bobby Fischer","v":true},
  {"id":"Q0181","en":"Petrosian could detect and avert danger twenty moves before it arose.","ta":"ஆபத்து எழுவதற்கு இருபது நகர்வுகளுக்கு முன்பே பெட்ரோசியன் அதைக் கண்டறிந்து தடுத்துவிடுவான்.","author":"Bobby Fischer","v":true},
  {"id":"Q0336","en":"In chess, one must think like a mathematician and dream like an artist.","ta":"சதுரங்கத்தில் கணிதவியலாளர் போலச் சிந்தித்து, கலைஞர் போலக் கனவு காண வேண்டும்.","author":"Rashid Nezhmetdinov","v":true},
  {"id":"Q0085","en":"Excelling at chess has long been considered a symbol of more general intelligence. That is an incorrect assumption in my view, as pleasant as it might be.","ta":"சதுரங்கத்தில் சிறப்படைவது பொதுவான அறிவின் அடையாளம் என்று நீண்ட காலமாகக் கருதப்படுகிறது. அது எவ்வளவு இனிமையாக இருந்தாலும், என் பார்வையில் அது தவறான கருத்தே.","author":"Garry Kasparov","v":true},
  {"id":"Q0071","en":"Fischer is the most wonderful genius to have descended from the chess heavens.","ta":"சதுரங்க வானத்திலிருந்து இறங்கிய மிக அற்புதமான மேதை ஃபிஷர்.","author":"Mikhail Tal","v":true},
  {"id":"Q0347","en":"The beauty of a queen is her power over the whole board.","ta":"முழுப் பலகையின் மீதும் தனக்கிருக்கும் ஆற்றலில்தான் அரசியின் அழகு நிற்கிறது.","author":"Mikhail Tal","v":true},
  {"id":"Q0107","en":"Many have become chess masters, but no one has become the master of chess.","ta":"பலர் சதுரங்க மாஸ்டர்கள் ஆகிவிட்டனர்; ஆனால் சதுரங்கத்தின் மாஸ்டர் என்று யாரும் ஆகவில்லை.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0070","en":"Silent moves often make a stronger impression than a wild combination with tremendous sacrifices.","ta":"மகத்தான தியாகங்கள் நிறைந்த வேகமான சேர்க்கை நகர்வுகளைவிட, அமைதியான நகர்வுகள் அடிக்கடி வலுவான தாக்கத்தை ஏற்படுத்துகின்றன.","author":"Mikhail Tal","v":true},
  {"id":"Q0355","en":"In chess, the simplest move is often the strongest.","ta":"சதுரங்கத்தில் எளிமையான நகர்வே அடிக்கடி மிக வலுவான நகர்வாக இருக்கும்.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0358","en":"Chess is a game of dreams that come true on the board.","ta":"பலகையில் நிறைவேறும் கனவுகளின் விளையாட்டு சதுரங்கம்.","author":"Boris Spassky","v":true},
  {"id":"Q0312","en":"Chess asks one simple question: who thinks more clearly?","ta":"யார் தெளிவாகச் சிந்திக்கிறார் என்ற ஒரே எளிய கேள்வியை சதுரங்கம் கேட்கிறது.","author":"Mikhail Botvinnik","v":true},
  {"id":"Q0118","en":"Chess is not a science, at least not exclusively a science. The proportion is roughly one quarter science, one quarter art, and all the rest is battle.","ta":"சதுரங்கம் ஒரு அறிவியல் அல்ல — குறைந்தபட்சம் முழுமையான அறிவியல் அல்ல. அதன் பங்கீடு ஏறக்குறைய கால் பங்கு அறிவியல், கால் பங்கு கலை, மீதி அனைத்தும் போர்.","author":"Max Euwe and Hans Kramer","v":true},
  {"id":"Q0268","en":"A chess player's memory is his library; study is his daily bread.","ta":"சதுரங்க வீரனின் நினைவாற்றலே அவனது நூலகம்; படிப்பே அவனது தினசரி உணவு.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0208","en":"A good opening gives you the chance to play a good middlegame.","ta":"நல்ல தொடக்க ஆட்டம், நல்ல நடு ஆட்டத்தை விளையாடும் வாய்ப்பைத் தருகிறது.","author":"Anatoly Karpov","v":true},
  {"id":"Q0018","en":"Every chess player should have a hobby.","ta":"ஒவ்வொரு சதுரங்க வீரனுக்கும் ஒரு பொழுதுபோக்கு இருக்க வேண்டும்.","author":"Savielly Tartakower","v":true},
  {"id":"Q0325","en":"The best way to learn the endgame is to study the great masters.","ta":"இறுதி ஆட்டத்தைக் கற்கச் சிறந்த வழி, மாபெரும் மாஸ்டர்களின் ஆட்டங்களைப் படிப்பதே.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0262","en":"The player who masters the art of patience is the player who wins in the end.","ta":"பொறுமையின் கலையைத் திறமையுடன் கையாளும் வீரனே இறுதியில் வெல்கிறான்.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0136","en":"In chess, the small things are the ones that matter.","ta":"சதுரங்கத்தில் சிறிய விஷயங்கள்தான் முக்கியமானவை.","author":"Anatoly Karpov","v":true},
  {"id":"Q0317","en":"Chess is a joy that grows with every game.","ta":"ஒவ்வொரு ஆட்டத்திலும் வளர்ந்துகொண்டே போகும் இன்பம் சதுரங்கம்.","author":"Bobby Fischer","v":true},
  {"id":"Q0065","en":"You know, I am finished with the old chess, because it is all just a lot of book and memorization, you know.","ta":"பழைய சதுரங்கத்துடன் எனக்கு முடிந்துவிட்டது; அதெல்லாம் புத்தகப் படிப்பும் மனப்பாடமும் மட்டுமே.","author":"Bobby Fischer","v":true},
  {"id":"Q0298","en":"Chess is the preparation for a grand adventure on the board.","ta":"பலகையில் நடக்கும் பெருஞ்சாகசத்திற்கான தயாரிப்பே சதுரங்கம்.","author":"Siegbert Tarrasch","v":true},
  {"id":"Q0112","en":"Chess is not for timid souls.","ta":"சதுரங்கம் தைரியமற்ற உள்ளங்களுக்கானது அல்ல.","author":"Wilhelm Steinitz","v":true},
  {"id":"Q0120","en":"Pawn endings are to chess what putting is to golf.","ta":"சதுரங்கத்தில் சிப்பாய் முடிவாட்டங்கள் வகிப்பது, கோல்ஃப்பில் புட்டிங் வகிப்பதற்கு நிகர்.","author":"C.J.S. Purdy","v":true},
  {"id":"Q0038","en":"I like the moment when I break a man's ego.","ta":"ஒருவனின் அகங்காரத்தை நான் உடைக்கும் தருணம் எனக்குப் பிடிக்கும்.","author":"Bobby Fischer","v":true},
  {"id":"Q0281","en":"The best time to think is before you move.","ta":"சிந்திக்கச் சிறந்த நேரம் நகருவதற்கு முன்பே.","author":"Bobby Fischer","v":true},
  {"id":"Q0096","en":"The threat is stronger than its execution.","ta":"அச்சுறுத்தலே அதைச் செயல்படுத்துவதைவிட வலிமையானது.","author":"Aron Nimzowitsch","v":true},
  {"id":"Q0004","en":"The hardest game to win is a won game.","ta":"வென்றுவிட்ட ஒரு ஆட்டத்தை மீண்டும் வெல்வதே மிகக் கடினமானது.","author":"Emanuel Lasker","v":true},
  {"id":"Q0299","en":"A chess player thinks with his head, not with his hands.","ta":"சதுரங்க வீரன் கைகளால் அல்ல, தலையால்தான் சிந்திக்கிறான்.","author":"Alexander Alekhine","v":true},
  {"id":"Q0073","en":"It is difficult to play against Einstein's theory.","ta":"ஐன்ஸ்டீனின் கோட்பாட்டுக்கு எதிராக விளையாடுவது கடினம்.","author":"Mikhail Tal","v":true},
  {"id":"Q0089","en":"Combinations have always been the most intriguing aspect of chess.","ta":"சேர்க்கை நகர்வுகள் என்றுமே சதுரங்கத்தின் மிகவும் கவர்ச்சியான அம்சமாக இருந்துள்ளன.","author":"Alexander Alekhine","v":true},
  {"id":"Q0030","en":"Chess is more than a game; it is an intellectual pastime that has some art and a lot of science.","ta":"சதுரங்கம் வெறும் விளையாட்டு அல்ல; சிறிதளவு கலையும் நிறைய அறிவியலும் கொண்ட ஒரு அறிவுசார் பொழுதுபோக்கு.","author":"José Raúl Capablanca","v":true},
  {"id":"Q0125","en":"Chess is ruthless: you have got to be prepared to kill people.","ta":"சதுரங்கம் இரக்கமற்றது; எதிரியை வீழ்த்தத் தயாராக இருக்க வேண்டும்.","author":"Nigel Short","v":true},
  {"id":"Q0137","en":"The threat of defeat is more terrible than defeat itself.","ta":"தோல்வியின் அச்சுறுத்தல், தோல்வியையே விடக் கொடியது.","author":"Anatoly Karpov","v":true},
  {"id":"Q0044","en":"My opponents make good moves too. Sometimes I do not take these things into consideration.","ta":"என் எதிரிகளும் நல்ல நகர்வுகளையே செய்கிறார்கள். சில நேரங்களில் நான் இதைக் கருத்தில் கொள்வதில்லை.","author":"Bobby Fischer","v":true},
  {"id":"Q0264","en":"Chess is a struggle against oneself more than against the opponent.","ta":"எதிரிக்கு எதிரான போராட்டத்தைவிட, சொந்த ஆளுக்கு எதிரான போராட்டமே சதுரங்கம்.","author":"Viktor Korchnoi","v":true},
  {"id":"Q0351","en":"The art of chess is the art of giving the right value to every piece.","ta":"ஒவ்வொரு காய்க்கும் சரியான மதிப்பை வழங்கும் கலையே சதுரங்கக் கலை.","author":"Capablanca","v":true},
  {"id":"Q0293","en":"Chess is the best teacher of logical thinking.","ta":"தர்க்க சிந்தனையின் சிறந்த ஆசிரியர் சதுரங்கம்.","author":"Botvinnik","v":true},
  {"id":"Q0216","en":"In chess, one learns to see the whole board, not just the piece in hand.","ta":"சதுரங்கத்தில் கையில் இருக்கும் காயை மட்டுமல்ல, முழுப் பலகையையும் பார்க்கக் கற்றுக்கொள்கிறோம்.","author":"Bobby Fischer","v":true},
  {"id":"Q0094","en":"The centre is the Balkans of the chessboard; fighting may at any time break out there.","ta":"மையப் பகுதி சதுரங்கப் பலகையின் பால்கன் பகுதி; எந்த நேரத்திலும் அங்கே போர் மூளலாம்.","author":"Rudolf Spielmann","v":true},
];

export default gmQuotes;
